// Питання Крок 1 з анатомії, відібрані з офіційних буклетів. Генерується tools/krok/parse_krok.py
window.KROK1={"source": "Центр тестування МОЗ України, офіційні збірники Крок 1 «Медицина» 2007–2024 і «Стоматологія» 2015–2017 (укр.); правильна відповідь у збірниках — A", "updated": "2026-09-05", "questions": [{"id": "735e948122", "year": 2024, "years": [2024], "n": 3, "q": "У пацієнта спостерігається колоторізана рана нижнього відділу задньої стінки пахвової ямки. Які м’язи пошкоджено?", "options": {"A": "Найширший м’яз спини", "B": "Триголовий м’яз плеча", "C": "Великий грудний м’яз", "D": "Дельтоподібний м’яз", "E": "Підостьовий м’яз"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:22"}, {"id": "82a76628c4", "year": 2023, "years": [2023, 2024], "n": 5, "q": "У пацієнта розгладжена права носогубна складка, розширена права очноямкова щілина (її не вдається замружити, тому що повіки не змикаються), виникають труднощі під час розмови та вживання їжі (їжа застрягає між щокою i зубами). Який нерв уражено?", "options": {"A": "N. facialis dexter", "B": "N. abduceus dexter", "C": "N. glossopharyngeus sinister", "D": "N. vagus dexter", "E": "N. trigeminus dexter"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:12"}, {"id": "eabf7facd0", "year": 2024, "years": [2024], "n": 6, "q": "У чоловіка віком 35 років під час травми задньої поверхні плеча пошкоджено променевий нерв i артеріальна судина, що проходить поруч з ним в canalis humeromuscularis. Яку артерію пошкоджено?", "options": {"A": "А. profunda brachii", "B": "А. axillaris", "C": "А. radialis", "D": "А. ulnaris", "E": "А. brachialis"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "c25582eafb", "year": 2024, "years": [2024], "n": 9, "q": "Під час обстеження пацієнта, який звернувся у неврологічне відділення, виявлено: зглаженість лобних складок, неможливість примружити очі, кут рота опущений, симтом паруса. Який нерв пошкоджений?", "options": {"A": "Лицевий", "B": "Окоруховий", "C": "Трійчастий", "D": "Блукаючий", "E": "Додатковий"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:11"}, {"id": "e2456b0ad4", "year": 2024, "years": [2024], "n": 12, "q": "Пацієнта шпиталізовано із пораненням великого поперекового м’яза. Чоловік утратив можливість розгинати гомілку в колінному суглобі. Який нерв ушкоджено в цьому разі?", "options": {"A": "Стегновий", "B": "Клубово-підчеревний", "C": "Клубово-пахвинний", "D": "Статево-стегновий", "E": "Затульний"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:7"}, {"id": "dc8ef34212", "year": 2024, "years": [2024], "n": 12, "q": "Після порушення кровопостачання головного мозку пацієнт утратив здатність до написання літер i цифр. У якій частині мозку виникла патологія?", "options": {"A": "Lobus frontalis", "B": "Lobus occipitalis", "C": "Lobus temporalis", "D": "Lobus parietalis", "E": "Insula"}, "answer": "A", "score": 9.4, "prof": "med", "topic": "c1:m2:2"}, {"id": "87ea874be6", "year": 2024, "years": [2024], "n": 16, "q": "Під час рентгенологічного обстеження виявлено: перелом основи черепа. Лінія перелому проходить через остистий i круглий отвори. Яка кістка пошкоджена внаслідок травми?", "options": {"A": "Клиноподібна", "B": "Скронева", "C": "Решітчаста", "D": "Лобова", "E": "Потилична"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:11"}, {"id": "0c32902039", "year": 2024, "years": [2024], "n": 16, "q": "У пацієнта порушений зір у бічних половинах полів зору обох очей (бітемпоральна геміанопсія). Яка нервова структура уражена?", "options": {"A": "Зорове перехрестя", "B": "Лівий зоровий тракт", "C": "Правий зоровий тракт", "D": "Сітківка ока", "E": "Зорові нерви"}, "answer": "A", "score": 3.8, "prof": "med"}, {"id": "eb2540b197", "year": 2024, "years": [2024], "n": 26, "q": "У пацієнта сенсорна афазія, не розуміє зверненого до нього мовлення. Яка локалізація ураження нервової системи?", "options": {"A": "Верхня скронева звивина", "B": "Середня скронева звивина", "C": "Нижня лобова звивина", "D": "Верхня лобова звивина", "E": "Середня лобова звивина"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:10"}, {"id": "1157c8d7d3", "year": 2024, "years": [2024], "n": 31, "q": "У жінки віком 37 років виявлено: пухлина розмірами 3х4 см, на 1 см нижче місця входження стравоходу до шлунка. Яка частина шлунка уражена пухлиною?", "options": {"A": "Cardia ventriculi", "B": "Corpus ventriculi", "C": "Fundus ventriculi", "D": "Pylorus ventriculi", "E": "Curvatura major"}, "answer": "A", "score": 5.7, "prof": "med", "topic": "c1:m1:29"}, {"id": "e64576412f", "year": 2024, "years": [2024], "n": 39, "q": "При гнійному отиті гноєм пошкоджено верхню стінку барабанної порожнини. У яку ямку черепа розповсюдився гній із барабанної порожнини? 0177V2", "options": {"A": "У середню черепну ямку", "B": "У задню черепну ямку", "C": "У передню черепну ямку", "D": "В очну ямку", "E": "У крилопіднебінну ямку"}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:8"}, {"id": "f341105921", "year": 2024, "years": [2024], "n": 40, "q": "У пацієнта обстежували сприйняття звуків за допомогою камертона. Під час розташування його біля зовнішнього вуха пацієнт не чув правим вухом звук камертона. Коли лікар розташував ніжку камертона на соскоподібному відростку пацієнт відчув звук. З ураженням якої частини слухової сенсорної системи це пов’язано?", "options": {"A": "Середнього вуха", "B": "Нижніх горбиків", "C": "Внутрішнього вуха", "D": "Слухового нерва", "E": "Медіального колінчастого тіла"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m2:14"}, {"id": "434fa74e41", "year": 2024, "years": [2024], "n": 42, "q": "У пацієнта спостерігається перекошене обличчя та сухість ока. Пошкодження якого нерва можна запідозрити?", "options": {"A": "Лицевого", "B": "Верхньощелепного", "C": "Нижньощелепного", "D": "Додаткового", "E": "Під’язикового"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:11"}, {"id": "1f3e38e49d", "year": 2024, "years": [2024], "n": 44, "q": "При гнійному отиті гноєм пошкоджено верхню стінку барабанної порожнини. У яку ямку черепа розповсюдився гній із барабанної порожнини?", "options": {"A": "У середню черепну ямку", "B": "У задню черепну ямку", "C": "У передню черепну ямку", "D": "В очну ямку", "E": "У крилопіднебінну ямку"}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:8"}, {"id": "ce8dd9cf27", "year": 2024, "years": [2024], "n": 44, "q": "Яка велика артерія проходить позаду malleolus medialis в окремому фіброзноuk 5 му каналі?", "options": {"A": "A. tibialis posterior", "B": "A. dorsalis pedis", "C": "A. tibialis anterior", "D": "A. fibularis", "E": "A. malleolaris medialis"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "e57723a9d4", "year": 2024, "years": [2024], "n": 46, "q": "Пацієнтку шпиталізовано до гінекологічного відділення з підозрою на внутрішньоочеревинну кровотечу (позаматкова вагітність). Крізь який утвір проводять пункцію для термінового діагностування кровотечі?", "options": {"A": "Заднє склепіння піхви", "B": "Переднє склепіння піхви", "C": "Шийку матки", "D": "Матковий зів", "E": "Передню стінку піхви"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:18"}, {"id": "00879cc342", "year": 2024, "years": [2024], "n": 46, "q": "У пацієнта спостерігається травма м’яких тканин i тім’яних кісток у ділянці їх з’єднання між собою, яка супроводжується сильною кровотечею. Яке судинне утворення пошкоджене?", "options": {"A": "Sinus sagittalis superior", "B": "Sinus transversus", "C": "Sinus petrosus superior", "D": "Sinus rectus", "E": "Sinus sagittalis inferior"}, "answer": "A", "score": 9.0, "prof": "med", "tag": "angio"}, {"id": "f6f56ebc89", "year": 2024, "years": [2024], "n": 48, "q": "У жінки віком 28 років виявлено позаматкову вагітність, яка ускладнилася розривом маткової труби. У який простір очеревини можливе попадання крові?", "options": {"A": "Прямокишково-матковий", "B": "Міхурово-матковий", "C": "Правий брижовий синус", "D": "Лівий брижовий синус", "E": "Міжсигмоподібний синус"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:32"}, {"id": "05a0087dfc", "year": 2024, "years": [2024], "n": 48, "q": "Після крововиливу у ліву півкулю головного мозку пацієнт втратив здатність говорити. У басейні якої артерії відбувся тромбоз?", "options": {"A": "Arteria cerebri media", "B": "Arteria cerebri anterior", "C": "Arteria cerebri posterior", "D": "Arteria communicans anterior", "E": "Arteria communicans posterior"}, "answer": "A", "score": 9.8, "prof": "med", "topic": "c1:m2:3"}, {"id": "0ffd3754b3", "year": 2024, "years": [2024], "n": 48, "q": "У пацієнта на рівні 4-го грудного хребця рентгеноскопічно діагностовано стороннє тіло стравоходу. У ділянці якого стравохідного звуження зупинилося стороннє тіло?", "options": {"A": "Аортального", "B": "Глоткового", "C": "Біфуркаційного", "D": "Діафрагмального", "E": "Абдомінального"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "e02b5df1ca", "year": 2024, "years": [2024], "n": 49, "q": "Яка велика артерія проходить позаду malleolus medialis в окремому фіброзному каналі?", "options": {"A": "A. tibialis posterior", "B": "A. dorsalis pedis", "C": "A. tibialis anterior", "D": "A. fibularis", "E": "A. malleolaris medialis"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "d5975ae403", "year": 2024, "years": [2024], "n": 67, "q": "Пацієнтку віком 50 років шпиталізовано із закритою черепно-мозковою травмою у ділянці потиличної кістки. Під час огляду спостерігається: порушення ходи i рівноваги, тремор рук. Яка частина головного мозку пошкоджена?", "options": {"A": "Мозочок", "B": "Довгастий мозок", "C": "Міст", "D": "Проміжний мозок", "E": "Спинний мозок"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:8"}, {"id": "ec992a2959", "year": 2024, "years": [2024], "n": 67, "q": "Під час футбольного матчу гравець отримав травму колінного суглоба. На рентгенівській плівці помітно виражений перелом кістки, що лежить у товщі сухожилка чотириголового м’яза стегна. До якої з нижченаведених груп кісток належить ця кістка?", "options": {"A": "Сесамоподібних", "B": "Плоских", "C": "Трубчастих", "D": "Повітроносних", "E": "Змішаних"}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:1"}, {"id": "09acf12817", "year": 2024, "years": [2024], "n": 71, "q": "До гінекологічного відділення шпиталізовано жінку з ознаками внутрішньої кровотечі та підозрою на позаматкову вагітність. У якому анатомічному утворенні, ймовірно, є накопичення крові?", "options": {"A": "Exavatio recto-uterina", "B": "Exavatio vesico-uterina", "C": "Fossa ischio-analis", "D": "Fossa paravesicalis", "E": "Fossa ovarica"}, "answer": "A", "score": 8.3, "prof": "med", "topic": "c1:m1:38"}, {"id": "f3fc229826", "year": 2024, "years": [2007, 2024], "n": 79, "q": "Після резекції середньої третини облітерованої тромбом стегнової артерії нижня кінцівка кровопостачається за рахунок обхідних анастомозів. Укажіть артерію, яка має основне значення у відновленні кровообігу.", "options": {"A": "Глибока стегнова артерія", "B": "Поверхнева огинальна артерія клубової кістки", "C": "Низхідна колінна артерія", "D": "Поверхнева надчеревна артерія", "E": "Глибока зовнішня соромітна артерія"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "1eccc16f0c", "year": 2024, "years": [2024], "n": 85, "q": "Під час аускультації серця пацієнта лікар вислухав систолічний шум у п’ятому міжреберному проміжку на 1 см до середини від лівої середньоключичної лінії. Патологія якого клапана спостерігається у цього пацієнта?", "options": {"A": "Мітрального", "B": "Аортального", "C": "Тристулкового", "D": "Клапана легеневого стовбура", "E": ""}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "aa1c9f0e9e", "year": 2024, "years": [2024], "n": 88, "q": "Лікар-хірург здійснює первинну хірургічну обробку глибокої різаної рани латеральної поверхні колінного суглоба. Яку зв’язку потрібно зшити лікарю?", "options": {"A": "Lig. collaterale fibulare", "B": "Lig. collaterale tibiale", "C": "Lig. popliteum obliquum", "D": "Lig. popliteum arcuatum", "E": "Lig. patellae"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:17"}, {"id": "cae8215cc6", "year": 2023, "years": [2023, 2024], "n": 92, "q": "Під час виконання оперативного втручання на колінному суглобі лікар повинен пам’ятати про артерію, що віддає найбільшу кількість гілок для утворення артеріальної суглобової сітки. Укажіть цю артерію.", "options": {"A": "A. poplitea", "B": "A. femoralis", "C": "A. tibialis anterior", "D": "A. tibialis posterior", "E": "A. fibularis"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "e733abc896", "year": 2024, "years": [2024], "n": 93, "q": "У пацієнта під час рентгенологічного дослідження виявлено затемнення в 0174V2 ділянці пазухи твердої мозкової оболони, яка проходить від півнячого гребня решітчастої кістки до внутрішнього потиличного виступу потиличної кістки. У ділянці якої пазухи виявлено патологічні зміни?", "options": {"A": "Sinus sagittalis superior", "B": "Sinus sagittalis inferior", "C": "Sinus transversus", "D": "Sinus rectus", "E": "Sinus sigmoideus"}, "answer": "A", "score": 7.0, "prof": "med", "topic": "c1:m1:9"}, {"id": "6b27b6547c", "year": 2024, "years": [2024], "n": 94, "q": "У пацієнта — травма колінного суглоба із розтрощенням надколінника. Сухожилля якого м’яза стегна можуть бути пошкоджені у разі цієї травми?", "options": {"A": "Чотириголового", "B": "Двоголового", "C": "Кравецького", "D": "Великого привідного", "E": "Довгого привідного"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:17"}, {"id": "2cd1472665", "year": 2024, "years": [2024], "n": 107, "q": "Під час оперативного втручання з приводу травми селезінки лікарюхірургу необхідно перев’язати артерію, що забезпечує її кровопостачання. Гілкою якої артеріальної судини вона є?", "options": {"A": "Truncus coeliacus", "B": "A. hepatica propria", "C": "A. hepatica communis", "D": "A. gastroduodenalis", "E": "A. gastrica sinistra"}, "answer": "A", "score": 6.5, "prof": "med", "tag": "angio"}, {"id": "45933bfdf0", "year": 2023, "years": [2023, 2024], "n": 108, "q": "У пацієнта травма кульшового суглоба. Рентгенологічно чітко виявлено внутрішньосуглобовий крововилив. Яка зв’язка розірвана?", "options": {"A": "Lig. capitis femoris", "B": "Lig. transversum acetabuli", "C": "Zona orbicularis", "D": "Lig. iliofemorale", "E": "Lig. ischiofemorale"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:8"}, {"id": "aa1d914b11", "year": 2024, "years": [2024], "n": 109, "q": "У пацієнта спостерігаються птоз (опущення повіки), розбіжна косоокість, порушення акомодації, розширення зіниць. Ядра якої пари черепних нервів уражені?", "options": {"A": "III", "B": "IV", "C": "V", "D": "VI", "E": "VII"}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:8"}, {"id": "b1a7912ecf", "year": 2024, "years": [2024], "n": 110, "q": "Хірург під час операції на щитоподібній залозі перев’язав верхню щитоподібну артерію. Гілку якої судини перев’язав лікар?", "options": {"A": "A. carotis externa", "B": "A. lingualis", "C": "A. facialis", "D": "A. carotis interna", "E": "A. pharyngea ascendens"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "8b14c129a7", "year": 2024, "years": [2024], "n": 116, "q": "Про можливе пошкодження якої судини повинен пам’ятати лікар під час виконання переднього серединного розтину шкіри та фасції шиї для термінової трахеотомії?", "options": {"A": "Аrcus venosus juguli", "B": "V. jugularis externa", "C": "V. jugularis interna", "D": "V. facialis", "E": "V. thyroidea media"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "12e33c5b58", "year": 2024, "years": [2024], "n": 117, "q": "У потерпілого травма голови, яка супроводжується артеріальною кровотечею в ділянці тім’яної кістки. Яка з гілок зовнішньої сонної артерії кровопостачає цю ділянку?", "options": {"A": "A. temporalis superficialis", "B": "A. occipitalis", "C": "A. facialis", "D": "A. maxillaris", "E": "A. auricularis posterior"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "89c701a259", "year": 2024, "years": [2024], "n": 126, "q": "Про можливе пошкодження якої судини повинен пам’ятати лікар під час uk 14 виконання переднього серединного розтину шкіри та фасції шиї, для термінової трахеотомії?", "options": {"A": "Аrcus venosus juguli", "B": "V. jugularis externa", "C": "V. jugularis interna", "D": "V. facialis", "E": "V. thyroidea media"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "1f44162ff0", "year": 2024, "years": [2024], "n": 131, "q": "У пацієнта порушений акт ковтання, осиплість голосу, поперхування рідкою їжею, м’яке піднебіння звисає. Які нерви іннервують м’язи м’якого піднебіння?", "options": {"A": "Блукаючий i нижньощелепний", "B": "Язикоглотковий i лицевий", "C": "Лицевий i щічний", "D": "Язикоглотковий i під’язиковий", "E": "Шийне сплетення"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:11"}, {"id": "e8c3a6ad3a", "year": 2024, "years": [2024], "n": 132, "q": "Лікар-хірург оперує на сигмоподібній ободовій кишці, зупиняючи кровотечу з аa. sigmoideae. Гілками якої артерії вони є?", "options": {"A": "A. mesenterica inferion", "B": "Truncus coeliacus", "C": "A. colica dextra", "D": "A. colica sinistra", "E": "A. mesenterica superior"}, "answer": "A", "score": 5.7, "prof": "med", "tag": "angio"}, {"id": "e66d3a11fb", "year": 2023, "years": [2023, 2024], "n": 150, "q": "У чоловіка, який надійшов до неврологічного відділення, діагностовано крововиливи у стовбур мозку. Цей стан супроводжувався порушенням дрібної моторики кистей рук, амімією обличчя та збільшенням тонусу соматичних м’язів. Ураження якої з перерахованих структур стовбуру мозку могло викликати цей стан?", "options": {"A": "Чорної субстанції", "B": "Ядра третьої пари черепно-мозкових нервів", "C": "Ретикулярної формації", "D": "Вестибулярного латерального ядра Дейтерса", "E": "Вестибулярного медіального ядра Швальбе"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "0649fe13e0", "year": 2023, "years": [2023], "n": 12, "q": "Після порушення кровопостачання головного мозку пацієнт утратив здатність до написання літер i цифр. В якій частині мозку виникла патологія?", "options": {"A": "Lobus frontalis", "B": "Lobus occipitalis", "C": "Lobus temporalis", "D": "Lobus parietalis", "E": "Insula"}, "answer": "A", "score": 9.4, "prof": "med", "topic": "c1:m2:2"}, {"id": "18abaf6f7c", "year": 2023, "years": [2023], "n": 28, "q": "У результаті травмування хребта у пацієнта відсутня пропріоцептивна чутливість нижньої половини тіла та нижніх кінцівок. Пошкодження якого провідного шляху може бути причиною цього?", "options": {"A": "Fasciculus gracilis (Голля)", "B": "Tr. spino-thalamicus lateralis", "C": "Tr. spino-thalamicus anterior", "D": "Fasciculus cuneatus (Бурдаха)", "E": "Tr. spino-cerebellaris ventralis (Говерса)"}, "answer": "A", "score": 4.8, "prof": "med", "topic": "c1:m2:17"}, {"id": "f23839b4e5", "year": 2023, "years": [2023], "n": 63, "q": "У дитини віком 12 років за 5 днів після захворювання на грип з’явився сильний головний біль, нудота, запаморочення та менінгеальні прояви. Дитина померла за добу після появи набряку мозку, що наростав. Під час розтину порожнини черепа виявлено: м’які мозкові оболонки набряклі, повнокровні, дифузно просякнуті рідиною яскравочервоного кольору, звивини i борозни згладжені. Яке ускладнення грипу можна припустити в цьому разі?", "options": {"A": "Геморагічний менінгіт", "B": "Крововилив у мозок", "C": "Венозна гіперемія оболонок мозку", "D": "Гнійний лептоменінгіт", "E": "Серозний менінгіт"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:8"}, {"id": "a714a0456d", "year": 2023, "years": [2023], "n": 65, "q": "Пацієнту встановлено діагноз: водянка яєчка (гідроцеле). Яка оболонка яєчка утворює порожнину, усередині якої накопичується рідина?", "options": {"A": "Tunica vaginalis testis", "B": "Tunica dartos", "C": "Fascia spermatica interna", "D": "Fascia spermatica externa", "E": "Tunica albuginea"}, "answer": "A", "score": 7.4, "prof": "med", "topic": "c1:m1:37"}, {"id": "a187f9b159", "year": 2023, "years": [2023], "n": 91, "q": "Під час хірургічного лікування стегнової грижі лікар виділяє поверхневий отвір стегнового каналу. Яка анатомічна структура його утворює?", "options": {"A": "Hiatus saphenus", "B": "Fascia pectinea", "C": "Septum femorale", "D": "Fossa femoralis", "E": "Arcus iliopectineus"}, "answer": "A", "score": 7.8, "prof": "med"}, {"id": "32e53c06ad", "year": 2023, "years": [2023], "n": 104, "q": "У немовляти після народження в судинній системі відбуваються зміни, пов’язані із переходом від плацентарного кровообігу до легеневого. Яка з кровоносних судин у ході цього перетворюється на круглу зв’язку печінки?", "options": {"A": "V. umbilicalis", "B": "Ductus venosus", "C": "A. umbilicalis sinistra", "D": "A. umbilicalis dextra", "E": "Ductus arteriosus"}, "answer": "A", "score": 5.2, "prof": "med", "tag": "angio"}, {"id": "a602996675", "year": 2022, "years": [2022], "n": 2, "q": "Після ДТП у водія спостерігається деформація в середній третині лівої гомілки, сильний біль, особливо за спроби рухати лівою гомілкою. З рани виступають кінці кістки з тригранним перерізом, посилюється крововтрата. Пошкодження якої кістки є найімовірнішим?", "options": {"A": "Великогомілкової кістки", "B": "Малогомілкової кістки", "C": "Стегнової кістки", "D": "Надколінника", "E": "Надп’яткової кістки"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:7"}, {"id": "7792ccc7be", "year": 2022, "years": [2022], "n": 20, "q": "Унаслідок травми хребта у пацієнта відсутня пропріоцептивна чутливість нижньої половини тіла та нижніх кінцівок. Пошкодження якого провідного шляху може бути причиною такого стану пацієнта?", "options": {"A": "Fasciculus gracilis", "B": "Tr. spino-thalamicus lateralis", "C": "Tr. spino-thalamicus anterior", "D": "Fasciculus cuneatus", "E": "Tr. spino-cerebellaris ventralis"}, "answer": "A", "score": 4.8, "prof": "med", "topic": "c1:m2:17"}, {"id": "9da1200857", "year": 2022, "years": [2022], "n": 62, "q": "У пацієнта спостерігається перфораційна виразка задньої стінки шлунку. Куди виділятиметься вміст шлунку у цьому разі?", "options": {"A": "У чепцеву сумку", "B": "У передшлункову сумку", "C": "У печінкову сумку", "D": "У правий брижовий синус", "E": "У лівий брижовий синус"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:29"}, {"id": "b6aad409c2", "year": 2022, "years": [2022], "n": 66, "q": "Під час аутопсії плода виявлено епідуральну гематому, яка утворилася внаслідок розриву серповидного синуса i намета мозочка.Проявом патології якого періоду розвитку можливе таке ушкодження?", "options": {"A": "Інтранатального періоду", "B": "Перинатального періоду", "C": "Антенатального періоду", "D": "Постнатального періоду", "E": "Періоду прогенеза"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:8"}, {"id": "e05e0bee5c", "year": 2022, "years": [2022], "n": 76, "q": "Під час операції хірургу треба знайти місце утворення ворітної печінкової вени. Укажіть це місце.", "options": {"A": "За головкою підшлункової залози", "B": "За тілом підшлункової залози", "C": "За шлунком", "D": "На задній стінці печінкової сумки", "E": "У печінково-шлунковій зв’язці"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "c288fa904a", "year": 2022, "years": [2022], "n": 82, "q": "У клініку звернувся пацієнт після травми голови зі скаргами на втрату раніше набутих професійних навичок (праксії). Яка ділянка кори головного мозку ушкоджена?", "options": {"A": "Gyrus supramarginalis", "B": "Gyrus angularis", "C": "Gyrus precentralis", "D": "Gyrus parietalis superior", "E": "Gyrus temporalis superior"}, "answer": "A", "score": 9.0, "prof": "med", "topic": "c1:m2:3"}, {"id": "81653f7dc6", "year": 2022, "years": [2022], "n": 104, "q": "Під час оперативного втручання з приводу травми селезінки хірургу треба виділити артерію, що забезпечує її кровопостачання. Гілкою якої судини є ця артерія?", "options": {"A": "Truncus coeliacus", "B": "A. hepatica propria", "C": "A. hepatica communis", "D": "A. gastroduodenalis", "E": "A. gastrica sinistra"}, "answer": "A", "score": 6.5, "prof": "med", "tag": "angio"}, {"id": "41fa8451a9", "year": 2022, "years": [2022], "n": 113, "q": "Під час операції на органах заднього середостіння існує ризик пошкодження нервів, розташованих поруч зі стравоходом. Назвіть ці нерви.", "options": {"A": "Блукаючі нерви", "B": "Додаткові нерви", "C": "Діафрагмові нерви", "D": "Міжреберні нерви", "E": "Язикоглоткові нерви"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:29"}, {"id": "64001639da", "year": 2022, "years": [2022], "n": 120, "q": "Під час оперативного втручання з приводу пахвинної кили хірург виділяє поверхневе пахвинне кільце. Похідні апоневрозу якого з м’язів утворюють більшість його стінок?", "options": {"A": "M. obliquus externus abdominis", "B": "M. obliquus internus abdominis", "C": "M. transversus abdominis", "D": "M. psoas major", "E": "M. rectus abdominis"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:21"}, {"id": "f85d2657de", "year": 2018, "years": [2018], "n": 17, "q": "Хворій виконують операцію на щитоподібній залозі. Гілки яких артерій повинен перев’язати хірург під час операції?", "options": {"A": "Верхня та нижня щитоподібна", "B": "Верхня та нижня гортанна", "C": "Верхня щитоподібна та щитошийний стовбур", "D": "Верхня щитоподібна та висхідна шийна", "E": "Висхідна шийна та глибока шийна"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "f7f05429df", "year": 2018, "years": [2018], "n": 22, "q": "При рентгенобстеженні у пацієнта протитуберкульозного диспансера діагностована пухлина в правій легені. Оператор при виконанні хірургічного втручання видалив середню частку правої легені, яка включає:", "options": {"A": "Segmentum laterale et segmentum mediale", "B": "Segmentum basale anterius et posterius", "C": "Segmentum anterius et segmentum apicale", "D": "Segmentum lingualare superius et inferius", "E": "Segmentum apicale (superius) et segmentum basale mediale"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:35"}, {"id": "5c90da3615", "year": 2018, "years": [2018], "n": 27, "q": "Після перенесеного запального захворювання у хворого виникло неповне відведення очного яблука в латеральну сторону. Який нерв у хворого пошкоджений?", "options": {"A": "Відвідний", "B": "Окоруховий", "C": "Блоковий", "D": "Зоровий", "E": "Лицевий"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:12"}, {"id": "080d644f70", "year": 2018, "years": [2018], "n": 43, "q": "У хворої 45-ти років виявлений рак молочної залози. У які регіонарні лімфатичні вузли можливе розповсюдження метастазів?", "options": {"A": "Пахвові, білягрудинні", "B": "Черевної порожнини, шиї", "C": "Шиї, білягрудинні", "D": "Білягрудинні, бронхомедіастинальні", "E": "Аортальні, бронхомедіастинальні"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "8fe67436eb", "year": 2018, "years": [2018], "n": 65, "q": "Швидкою допомогою в приймальне відділення доставлений хворий з кривавим блюванням. В анамнезі цироз печінки. Пошкодження яких вен найбільш ймовірне в даному випадку?", "options": {"A": "Стравохідні", "B": "Верхні брижові", "C": "Печінкові", "D": "Нижні брижові", "E": "Селезінкові"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "95cef262de", "year": 2018, "years": [2018], "n": 91, "q": "До лікарні надійшов пацієнт з перфоративною виразкою задньої стінки шлунка. Який елемент очеревини хірург під час операції повинен ретельно обстежити?", "options": {"A": "Чепцева сумка", "B": "Печінкова сумка", "C": "Передшлункова сумка", "D": "Лівий бічний канал", "E": "Права брижова пазуха"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:29"}, {"id": "276df7e2e4", "year": 2018, "years": [2018], "n": 94, "q": "Внаслідок травми низу передньої стінки живота у хворої ушкоджена зв’язка, що розташована у пахвинному каналі. Яка це зв’язка?", "options": {"A": "Ligamentum teres uteri", "B": "Ligamentum latum uteri", "C": "Ligamentum ovarium proprium", "D": "Ligamentum lacunare", "E": "Ligamentum inguinale"}, "answer": "A", "score": 11.0, "prof": "med", "topic": "c1:m1:21"}, {"id": "565ea6be14", "year": 2018, "years": [2018], "n": 95, "q": "Після перенесеного ГРЗ у хворої спостерігається утруднене носове дихання, підвищена температура, головний біль, сльозовиділення, болючість під час пальпації в ділянці fossa canina справа. Запаленням якої пазухи ускладнилося захворювання?", "options": {"A": "Sinus maxillaris dexter", "B": "Sinus frontalis dexter", "C": "Sinus sphenoidalis dexter", "D": "Cellulae ethmoidales anteriores", "E": "Cellulae ethmoidales posteriores"}, "answer": "A", "score": 4.7, "prof": "med", "topic": "c1:m1:12"}, {"id": "75ee5492be", "year": 2018, "years": [2018], "n": 123, "q": "У хворого кровотеча з поперечної ободової кишки. Чим кровопостачається цей відділ товстої кишки?", "options": {"A": "Arteria colica media", "B": "Arteria mesenterica inferior", "C": "Arteria sigmoidea", "D": "Arteria ileocolica", "E": "Arteria lienalis"}, "answer": "A", "score": 10.2, "prof": "med", "tag": "angio"}, {"id": "a655eb8c90", "year": 2018, "years": [2018], "n": 150, "q": "Лікар встановив у хворого наявність ураження парасимпатичного ядра IX пари черепних нервів. Яке ядро уражене в даному випадку?", "options": {"A": "Nucleus salivatorius inferior", "B": "Nucleus salivatorius superior", "C": "Nucleus thoracicus", "D": "Nucleus tractus solitarii", "E": "Nucleus ambiguus"}, "answer": "A", "score": 10.2, "prof": "med", "topic": "c1:m1:8"}, {"id": "bf2b96b289", "year": 2018, "years": [2018], "n": 150, "q": "У онкологічного хворого буде проведе оперативне втручання на низхідному відділі ободової кишки. Вкажіть найважливіше джерело його кровопостачання:", "options": {"A": "Нижня брижова артерія", "B": "Верхня брижова артерія", "C": "Черевний стовбур", "D": "Середня ободова артерія", "E": "Селезінкова артерія"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "e6f27d386c", "year": 2018, "years": [2018], "n": 155, "q": "У клініку потрапив хворий 24-х років, у якого внаслідок проникного пораненвний ня ока відбулося витікання склоподібного тіла. Це призвело до відшарування сітчастої оболонки. Який шар сітківки, міцно зрощений із судинною оболонкою, не відшарувався?", "options": {"A": "Пігментний епітелій", "B": "Шар паличок i колбочок", "C": "Гангліонарний", "D": "Зовнішній ядерний", "E": "Внутрішній ядерний"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:11"}, {"id": "39a69a08b3", "year": 2018, "years": [2018], "n": 171, "q": "У хворого хронічний нежить. Набряк слизової оболонки носової порожнини призводить до порушення функції рецепторів нюхового нерва, які розташовані в нюховій ділянці носової порожнини. Через яке утворення волокна цього нерва потрапляють до передньої черепної ямки?", "options": {"A": "Lamina cribrosa os ethmoidale", "B": "Foramen ethmoidale anterior", "C": "Foramen ethmoidale posterior", "D": "Foramen sphenopalatinum", "E": "Foramen incisivum"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:12"}, {"id": "f8e8b4bf4b", "year": 2018, "years": [2018], "n": 174, "q": "В травматологічне відділення потрапив постраждалий з травмою зап’ястка та клінікою ушкодження нерва, що проходить в каналі зап’ястка. Який це нерв?", "options": {"A": "N. medianus", "B": "N. ulnaris", "C": "N. radialis", "D": "N. axillaris", "E": "N. musculocutaneus"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:5"}, {"id": "da8cabd65e", "year": 2018, "years": [2018], "n": 176, "q": "У чоловіка пахвинна грижа. Через який отвір виходить грижевий мішок?", "options": {"A": "Anulus superficialis canalis inguinalis", "B": "Foramen suprapiriforme", "C": "Linea alba", "D": "Anulus profundus canalis inguinalis", "E": "Anulus femoralis"}, "answer": "A", "score": 9.4, "prof": "med", "topic": "c1:m1:21"}, {"id": "6f33760f00", "year": 2018, "years": [2018], "n": 189, "q": "У хворого порушено кровопостачання переднього соскоподібного м’яза лівого шлуночка. Яка артерія серця його кровопостачає?", "options": {"A": "Ramus interventricularis anterior", "B": "Ramus interventricularis posterior", "C": "A. coronaria dextra", "D": "Ramus circumflexus", "E": "Ramus marginalis"}, "answer": "A", "score": 10.6, "prof": "med", "tag": "angio"}, {"id": "990933efb3", "year": 2018, "years": [2018], "n": 197, "q": "У травмованого чоловіка втрачена чутливість шкіри бічної поверхні передпліччя. Який з нервів плечового сплетення забезпечує чутливість травмованої ділянки?", "options": {"A": "N. musculucutaneus", "B": "N. medianus", "C": "N. ulnaris", "D": "N. axillaris", "E": "N. radialis"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:5"}, {"id": "002c18f4d7", "year": 2018, "years": [2018], "n": 200, "q": "Після перелому кісток кисті чоловік втратив змогу доторкатися великим пальцем кисті до мізинця. Під час огляду долонної поверхні кісті відмічається атрофія одного з м’язів долоні. Який м’яз уражений?", "options": {"A": "M. opponens policis", "B": "Mm. lumbricales", "C": "Mm. interossei", "D": "M. flexor digiti minimi", "E": "M. palmaris brevis НАВЧАЛЬНЕ ВИДАННЯ Центр тестування професійної компетентності фахівців з вищою освітою напрямів підготовки “Медицина” і “Фармація”. ЗБІРНИК ТЕСТОВИХ ЗАВДАНЬ ДЛЯ СКЛАДАННЯ ЛІЦЕНЗІЙНОГО ІСПИТУ: КРОК 1. ЗАГАЛЬНА ЛІКАРСЬКА ПІДГОТОВКА. Київ. Центр тестування професійної компетентності "}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:5"}, {"id": "9574e769d3", "year": 2017, "years": [2017], "n": 6, "q": "У хворого з пухлиною пошкоджено піраміди довгастого мозку. У якому з провідних шляхів порушиться проведення нервових імпульсів? вний", "options": {"A": "Tr. corticospinalis", "B": "Tr. corticonuclearis", "C": "Tr. corticopontinus", "D": "Tr. dentatorubralis", "E": "Tr. spinocerebellaris"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m2:9"}, {"id": "108e3e3d55", "year": 2015, "years": [2015, 2017], "n": 11, "q": "У хворого запалення легень ускладнилося ексудативним плевритом. В якому з перерахованих анатомічних утворень переважно може накопичуватися рідина?", "options": {"A": "Sinus costodiaphragmaticus pleurae", "B": "Sinus costomediastinalis pleurae", "C": "Sinus phrenicomediastinalis pleurae", "D": "Sinus transversus pericardii", "E": "Sinus obliquus pericardii"}, "answer": "A", "score": 4.8, "prof": "med", "topic": "c1:m1:35"}, {"id": "aa9c3aea3d", "year": 2017, "years": [2017], "n": 15, "q": "Пароніхій мізинця ускладнився флегмоною кисті та передпліччя. Нагнійний процес поширився по:", "options": {"A": "Vagina synovialis communis mm. flexorum", "B": "Vagina tendinis m. flexor pollicis longi", "C": "Canalis carpalis", "D": "Vagina tendinis m. flexor carpi radialis", "E": "Міжфасціальних просторах"}, "answer": "A", "score": 4.0, "prof": "med", "topic": "c1:m1:5"}, {"id": "4103413cd5", "year": 2017, "years": [2017], "n": 16, "q": "При видаленні жовчного міхура в лігатуру замість однієї a. cystyca була втягнена артерія, перев’язка якої призвела до некрозу правої частки печінки i смерті. Яка артерія була помилково перев’язана разом з a. cystyca? вний", "options": {"A": "Ramus dexter a. hepatica propria", "B": "А. hepatica communis", "C": "А. gasro-duodenalis", "D": "Ramus sinister a. hepatica propria", "E": "А. pancreato-duodenalis sup"}, "answer": "A", "score": 7.6, "prof": "med", "tag": "angio"}, {"id": "af3a6e7d65", "year": 2017, "years": [2017], "n": 25, "q": "Пункцію сечового міхура через передню черевну стінку, не займаючи очеревину, можливо виконати:", "options": {"A": "При наповненому сечовому міхурі", "B": "При пустому сечовому міхурі", "C": "Тільки у чоловіків", "D": "Тільки у жінок", "E": "Тільки у дітей ний"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:32"}, {"id": "2b356d096c", "year": 2017, "years": [2017], "n": 34, "q": "В результаті травми у чоловіка 47-ми років пошкоджені передні корінці спинного мозку. Відростки яких нейронів пошкоджені?", "options": {"A": "Аксони нейронів рухових соматичних та вегетативних ядер", "B": "Аксони чутливих псевдоуніполярних", "C": "Дендрити чутливих псевдоуніполярних", "D": "Дендрити рухових i аксони ядер бокових стовпів", "E": "Дендрити i аксони чутливих псевдоуніполярних ний"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:1"}, {"id": "435e04a8c8", "year": 2017, "years": [2017], "n": 42, "q": "При розтині тіла прозектор виявив, що легені збільшені в розмірах, бліді, м’якої консистенції, не спадаються, ріжуться з хрускотом. Мікроскопічно: розширення альвеолярних ходів, міжальвеолярні перегородки тонкі, є ознаки інтракапілярного склерозу. Для якого захворювання легенів характерна така морфологічна картина?", "options": {"A": "Емфізема", "B": "Пневмосклероз", "C": "Пневмоторакс", "D": "Ателектаз", "E": "Пневмонія"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:35"}, {"id": "bf8d543993", "year": 2017, "years": [2017], "n": 49, "q": "Хворому проводять правобічну пульмонектомію з приводу раку легені. Назвіть порядок розташування анатомічних утворів кореня правої легені (у напрямку зверху вниз):", "options": {"A": "Бронх, артерія, вени", "B": "Артерія, бронх, вени", "C": "Артерія, вени, бронх", "D": "Вени, артерія, бронх", "E": "Вени, бронх, артерія"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "6f8e221d73", "year": 2015, "years": [2015, 2017], "n": 61, "q": "У новонародженого малюка педіатр виявив, що отвір крайньої плоті за величиною не перевищує діаметр сечовивідного каналу i голівка статевого члена не може виходити через такий отвір. Як називається цей стан?", "options": {"A": "Фімоз", "B": "Епіспадія", "C": "Гіпоспадія", "D": "Парафімоз", "E": "Гермафродитизм"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:36"}, {"id": "894870a09d", "year": 2017, "years": [2017], "n": 69, "q": "У жінки, що звернулася до хірурга, визначається ущільнення у молочній залозі. У якому напрямку має провести розріз хірург під час операції для зменшення травмування дольки?", "options": {"A": "Радіально", "B": "Вертикально", "C": "Поперечно", "D": "Дугоподібно", "E": ""}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:12"}, {"id": "8e53ed2a91", "year": 2017, "years": [2012, 2017], "n": 76, "q": "Чоловіку 40-ка років за вимогою діагностичних тестів зробили лімфографію органів грудної порожнини. Хірург встановив, що пухлина вразила орган, з лімфатичних судин якого лімфа безпосередньо переходить в грудну протоку. Який це орган?", "options": {"A": "Стравохід", "B": "Трахея", "C": "Лівий головний бронх", "D": "Серце", "E": "Осердя"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "5fe6c67db0", "year": 2017, "years": [2017], "n": 83, "q": "У хворого діагностовано інфаркт задньої частини міжшлуночкової перегородки. В ділянці якої кровоносної судини виникло порушення кровообігу? ний", "options": {"A": "R. interventricularis posterior", "B": "R. marginalis dexter", "C": "R. atrialis intermedius", "D": "R. circumflexus", "E": "R. marginalis sinister"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "fa58745d92", "year": 2017, "years": [2017], "n": 104, "q": "Хворому на атеросклероз лікар порекомендував вживати молоко коров’яче незбиране, вершки, йогурти з високим вмістом жиру. Які негативні властивості молочного жиру не враховані лікарем?", "options": {"A": "Недостатній вміст ПНЖК для впливу на надлишок холестерину", "B": "Наявність насичених жирних кислот", "C": "Наявність ненасичених жирних кислот", "D": "Наявність фосфопротеїдів, стеринів", "E": "Наявність жиророзчинних вітамінів"}, "answer": "A", "score": 3.8, "prof": "stom", "topic": "c1:m1:12"}, {"id": "03bdc1b9da", "year": 2017, "years": [2017], "n": 110, "q": "Хворий звернувся до лікаря зі скаргами на болі в кульшовому суглобі та у всіх привідних м’язах i шкірі над ними при рухах. Який нерв ушкоджено?", "options": {"A": "Затульний нерв", "B": "Клубово-пахвинний нерв", "C": "Стегновий нерв", "D": "Латеральний шкірний нерв стегна", "E": "Задній шкірний нерв стегна"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:6"}, {"id": "e33529f002", "year": 2017, "years": [2017], "n": 124, "q": "Швидкість проведення збудження нервовими волокнами становить 120 м/с. Який з наведених чинників, перш за все, забезпечує таку швидкість?", "options": {"A": "Наявність мієлінової оболонки", "B": "Великий потенціал спокою", "C": "Велика амплітуда потенціалу дії", "D": "Малий поріг деполяризації", "E": "Великий фактор надійності"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:11"}, {"id": "e76b577489", "year": 2017, "years": [2017], "n": 141, "q": "У пацієнта перфоративна виразка передньої стінки шлунка. В яке похідне очеревини попаде вміст шлунка?", "options": {"A": "Передшлункова сумка", "B": "Чепцева сумка", "C": "Печінкова сумка", "D": "Правий брижовий синус", "E": "Лівий брижовий синус"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:29"}, {"id": "81f244d8f9", "year": 2017, "years": [2017], "n": 143, "q": "Жінка звернулася до лікаря зі скаргами на утруднення рухів язика. Обстеження головного мозку за допомогою ЯМР показало, що у хворої крововилив в нижньому відділі довгастого мозку. Про пошкодження якого ядра довгастого мозку у хворої можна думати?", "options": {"A": "Ядро під’язикового нерва", "B": "Нижнє слиновидільне ядро", "C": "Ядро додаткового нерва", "D": "Подвійне ядро", "E": "Одиноке ядро"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:28"}, {"id": "5ef47b55dd", "year": 2017, "years": [2017], "n": 146, "q": "У хворої виявлена ракова пухлина шийки матки. У які регіонарні лімфатичні вузли можливе розповсюдження метастазів?", "options": {"A": "Пахвинні i здухвинні", "B": "Поперекові i ниркові", "C": "Верхні i нижні брижові", "D": "Навколоміхурні i поперекові", "E": ""}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "508a8e1468", "year": 2017, "years": [2017], "n": 193, "q": "У хворого з підозрою на ”озену” з носоглотки були виділені грамнегативні палички, які утворювали капсулу на", "options": {"A": "Клебсієли", "B": "Сальмонели", "C": "Шигели", "D": "Хламідії", "E": "Мікоплазми"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:28"}, {"id": "c29b49b365", "year": 2017, "years": [2017], "n": 197, "q": "Хірург під час операції на щитоподібній залозі перев’язав верхню щитоподіний бну артерію. Гілку якої судини перев’язав лікар?", "options": {"A": "A. carotis externa", "B": "A. lingualis", "C": "A. facialis", "D": "A. carotis interna", "E": "A. pharyngea ascendens"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "a623781334", "year": 2017, "years": [2017], "n": 198, "q": "У постраждалого поверхневе поранення передньої ділянки шиї, спостерігається кровотеча. Кров темного кольору. Яку судину пошкоджено?", "options": {"A": "V. jugularis anterior", "B": "V. jugularis externa", "C": "V. jugularis interna", "D": "A. carotis externa", "E": "A. thyroidea superior"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "97f9281c52", "year": 2017, "years": [2017], "n": 200, "q": "У потерпілого перелом у ділянці бічної поверхні променево-зап’ясткового суглоба. Де найімовірніше відбувся перелом?", "options": {"A": "Шилоподібний відросток променевої кістки", "B": "Гачкувата кістка", "C": "Головчаста кістка", "D": "Шилоподібний відросток ліктьової кістки", "E": "Нижня третина плечової кістки НАВЧАЛЬНЕ ВИДАННЯ Центр тестування професійної компетентності фахівців з вищою освітою напрямів підготовки “Медицина” і “Фармація”. ЗБІРНИК ТЕСТОВИХ ЗАВДАНЬ ДЛЯ СКЛАДАННЯ ЛІЦЕНЗІЙНОГО ІСПИТУ: КРОК 1. ЗАГАЛЬНА ЛІКАРСЬКА ПІДГОТОВКА. Київ. Центр тестування професійної комп"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:5"}, {"id": "ce9b0ba221", "year": 2016, "years": [2016], "n": 1, "q": "У хворого після перелому верхньої третини плечової кістки розвинувся параліч задньої групи м’язів плеча i передпліччя. Який нерв пошкоджено?", "options": {"A": "Променевий", "B": "Ліктьовий", "C": "Серединний", "D": "М’язово-шкірний", "E": "Пахвовий"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:5"}, {"id": "6f0a401a7c", "year": 2016, "years": [2016], "n": 23, "q": "При травмі в області тазу у хворого на рентгенологічному знімку виявлено некроз головки стегнової кістки. Під час травми кульшового суглоба було пошкоджено зв’язку:", "options": {"A": "Головки стегнової кістки", "B": "Клубово-стегнова", "C": "Лобкова-стегнова", "D": "Сіднично-стегнова", "E": ""}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:6"}, {"id": "4894dc5045", "year": 2015, "years": [2015, 2016], "n": 44, "q": "Після автомобільної катастрофи юнак 23-х років звернувся до лікарні з різаною раною передньо-медіальної ділянки плеча, що супроводжується артеріальною кровотечею. Яка артерія уражена?", "options": {"A": "А. brachialis", "B": "А. radialis", "C": "А. axillaris", "D": "А. subscapularis", "E": "А. profunda brachii"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "4290034f7d", "year": 2016, "years": [2016], "n": 45, "q": "При обстеженні кровопостачання стопи, лікар обстежує пульсацію крупної артерії, яка проходить попереду articulatio talocruralis проміж сухожилками довгого розгинача великого пальця стопи та довгого розгинача пальців в окремому фіброзному каналі. Яка це артерія?", "options": {"A": "A. dorsalis pedis", "B": "A. tibialis anterior", "C": "A. tarsea medialis", "D": "A. tarsea lateralis", "E": "A. fibularis"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "177096df98", "year": 2015, "years": [2015, 2016], "n": 50, "q": "При ураженні задньої третини скроневої звивини лівої (домінантної) півкулі виникає:", "options": {"A": "Сенсорна афазія", "B": "Семантична афазія", "C": "Динамічна афазія", "D": "Аферентна моторна афазія", "E": "Еферентна моторна афазія"}, "answer": "A", "score": 4.6, "prof": "stom", "topic": "c1:m1:10"}, {"id": "6af0a0d954", "year": 2015, "years": [2015, 2016], "n": 52, "q": "При ураженні кори задньо-скроневотім’яної ділянки лівої півкулі (зона ТРО) виникає:", "options": {"A": "Семантична афазія", "B": "Сенсорна афазія", "C": "Динамічна афазія", "D": "Тотальна афазія", "E": "Аферентна моторна афазія"}, "answer": "A", "score": 4.2, "prof": "stom", "topic": "c1:m1:10"}, {"id": "00582bdc3c", "year": 2016, "years": [2016], "n": 54, "q": "У травматологічне відділення поступив чоловік з травмою правого плеча. При огляді встановлено перелом діафізу правої плечової кістки в середній третині зі зміщенням відламків, пальці правої кисті не розгинаються. Який нерв пошкоджено? вний", "options": {"A": "Променевий", "B": "Ліктьовий", "C": "Серединний", "D": "М’язово-шкірний", "E": "Пахвовий"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:5"}, {"id": "e48eb3f602", "year": 2016, "years": [2016], "n": 57, "q": "Чоловіку 40-ка років за результатами діагностичних тестів зробили лімфографію органів грудної порожнини. Хірург встановив, що пухлина вразила орган, з лімфатичних судин якого лімфа безпосередньо переходить в грудну протоку. Який це орган?", "options": {"A": "Стравохід", "B": "Трахея", "C": "Лівий головний бронх", "D": "Серце", "E": "Осердя"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "60e8c0e4b0", "year": 2015, "years": [2015, 2016], "n": 59, "q": "У людини травматичне пошкодження груднино-ключично-сосцеподібного м’яза. Це призвело до зменшення величини:", "options": {"A": "Резервного об’єму вдиху", "B": "Резервного об’єму видиху", "C": "Дихального об’єму", "D": "Залишкового об’єму", "E": "Функціональної залишкової ємності легенів"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:3"}, {"id": "a63f11981f", "year": 2016, "years": [2016], "n": 77, "q": "У хворого внаслідок тривалого хронічного захворювання головного мозку виникли мимовільні рухи, порушився тонус м’язів тулуба. На порушення якого провідного шляху вказують ці симптоми?", "options": {"A": "Tractus rubrospinalis", "B": "Tractus corticospinalis", "C": "Tractus corticonuclearis", "D": "Tractus spinothalamicus", "E": "Tractus tectospinalis"}, "answer": "A", "score": 7.0, "prof": "med", "topic": "c1:m1:19"}, {"id": "7f7b9bd4d0", "year": 2016, "years": [2016], "n": 92, "q": "У важкоатлета при підйомі штанги відбувся розрив грудної лімфатичної протоки. Вкажіть найбільш імовірне місце ушкодження:", "options": {"A": "Ділянка аортального отвору діафрагми", "B": "Ділянка попереково-крижового сполучення", "C": "Заднє середостіння", "D": "Місце впадіння у венозний кут", "E": "Ділянка шиї"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "77443ae41c", "year": 2016, "years": [2014, 2016], "n": 94, "q": "У хворої після видалення матки розвинулась гостра анурія (немає виділення сечі). Які анатомічні структури найімовірніше було пошкоджено при операції?", "options": {"A": "Сечоводи", "B": "Сечівник", "C": "Зовнішній сфінктер сечівника", "D": "Внутрішній сфінктер сечівника", "E": "Цибулинно-губчастий м’яз"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:36"}, {"id": "bee7320472", "year": 2016, "years": [2016], "n": 96, "q": "У чоловіка при обстеженні виявлено порушення кровообігу міокарда лівого передсердя. У басейні якої артерії відбулись порушення кровообігу?", "options": {"A": "Ліва вінцева", "B": "Права вінцева", "C": "Права та ліва вінцеві", "D": "Передня міжшлуночкова гілка лівої вінцевої артерії", "E": ""}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "598ee15bc6", "year": 2016, "years": [2016], "n": 97, "q": "У підлітка 13-ти років під час проведення рентгенографічного дослідження кульшового суглоба виявлено зону просвітлення шириною 3 мм між голівкою та діафізом стегнової кістки. Як слід оцінити таку ситуацію?", "options": {"A": "Як норму (незавершений процес окостеніння)", "B": "Як перелом шийки стегнової кістки", "C": "Як тріщину шийки стегнової кістки", "D": "Як вивих головки стегнової кістки", "E": "Як артефакт на рентгенологічній плівці"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:6"}, {"id": "2e37aaead6", "year": 2015, "years": [2011, 2015, 2016], "n": 111, "q": "У потерпілого з травмою голови у скроневій ділянці діагностовано епідуральну гематому. Яка з артерій найімовірніше пошкоджена?", "options": {"A": "Середня оболонкова", "B": "Середня мозкова", "C": "Поверхнева скронева", "D": "Передня оболонкова", "E": "Задня вушна"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "b246250985", "year": 2016, "years": [2016], "n": 121, "q": "Хвора 47-ми років страждає на гіпомоторну дискінезію товстого кишківника. Як модернізувати харчовий раціон з метою підвищення моторики кишківника?", "options": {"A": "У раціональній дієті збільшити кількість рослинного волокна та кисломолочних продуктів", "B": "У раціональній дієті збільшити кількість рослинних, кисломолочних продуктів та магнію", "C": "У раціональній дієті збільшити кількість рослинних білків, тваринних жирів, калію", "D": "У гіпоенергетичній дієті збільшити кількість рослинних білків, молочних продуктів, кальцію", "E": "У редукувальній білково-овочевій дієті збільшити кількість тваринних жирів та магнію"}, "answer": "A", "score": 3.8, "prof": "stom", "topic": "c1:m1:12"}, {"id": "6d66b2e2d5", "year": 2015, "years": [2015, 2016], "n": 122, "q": "У хворого під час комп’ютерної томографії грудної клітки діагностовано пухлину заднього нижнього середостіння. Яка з перерахованих структур стиснута пухлиною?", "options": {"A": "Aorta thoracica", "B": "Trachea", "C": "Arcus aortae", "D": "N. phrenicus", "E": "Vena cava superior"}, "answer": "A", "score": 4.9, "prof": "med", "topic": "c1:m1:35"}, {"id": "ebece2ad06", "year": 2015, "years": [2015, 2016], "n": 123, "q": "Під час операції холецистектомії у хірурга виникла необхідність визначити топографію загальної жовчної протоки. Злиттям яких проток утворюється дана анатомічна структура?", "options": {"A": "Загальної печінкової i міхурової проток", "B": "Загальної печінкової i правої печінкової проток", "C": "Загальної печінкової i лівої печінкової проток", "D": "Лівої печінкової i міхурової проток", "E": "Правої та лівої печінкових проток"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:31"}, {"id": "fff3fb61a9", "year": 2016, "years": [2014, 2016], "n": 123, "q": "У хворої встановлено порушення виділення тиреотропного гормону гіпофіза. Зі зниженням функцій якої частки гіпофіза це пов’язано?", "options": {"A": "Lobus anterior", "B": "Infundibulum", "C": "Lobus posterior", "D": "Pars intermedia", "E": ""}, "answer": "A", "score": 3.9, "prof": "med", "topic": "c1:m1:40"}, {"id": "8f721a4a3d", "year": 2016, "years": [2016], "n": 124, "q": "В онкологічне відділення поступив хворий з підозрою на пухлину легень. При обстеженні виявили локалізацію патології в нижній частці правої легені. Скільки бронхолегеневих сегментів має ця частка?", "options": {"A": "5", "B": "6", "C": "4", "D": "3", "E": "2"}, "answer": "A", "score": 5.0, "prof": "med", "topic": "c1:m1:35"}, {"id": "325914b597", "year": 2016, "years": [2016], "n": 173, "q": "У хворого виявлено зміну функції привушної слинної залози. Який з вузлів вегетативної нервової системи віддає післявузлові симпатичні волокна для неї?", "options": {"A": "Ganglion cervicale superius", "B": "Ganglion cervicothoracicum", "C": "Ganglion pterygopalatinum", "D": "Ganglion submandibulare", "E": "Ganglion oticum"}, "answer": "A", "score": 7.4, "prof": "med", "topic": "c1:m1:28"}, {"id": "1e3d51ed32", "year": 2016, "years": [2016], "n": 176, "q": "У хворого хронічна нежить. Набряк слизової оболонки носової порожнини призводить до порушення функції рецепторів нюхового нерва, які розташовані в нюховій ділянці носової порожнини. Через яке утворення волокна цього нерва потрапляють в передню черепну ямку?", "options": {"A": "Lamina cribrosa os ethmoidale", "B": "Foramen ethmoidale anterior", "C": "Foramen ethmoidale posterior", "D": "Foramen sphenopalatinum", "E": "Foramen incisivum"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:12"}, {"id": "88efb1178c", "year": 2016, "years": [2016], "n": 190, "q": "Оперуючи на наднирниковій залозі, хірург зупиняє кровотечу з артерії, що відходить до наднирникової залози від черевної аорти. Назвіть цю артерію:", "options": {"A": "A. suprarenalis media", "B": "A. renalis", "C": "A. suprarenalis superior", "D": "A. uprarenalis inferior", "E": "A. phrenica inferior"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "df77eb1e76", "year": 2016, "years": [2016], "n": 197, "q": "Після проведеної операції на шиї хворий втратив чутливість в її передній ділянці. Яка гілка шийного сплетення була пошкоджена під час операції?", "options": {"A": "Поперечний нерв шиї", "B": "Великий вушний нерв", "C": "Малий потиличний нерв", "D": "Надключичні нерви", "E": "Шийна петля"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:22"}, {"id": "30313bcbab", "year": 2016, "years": [2016], "n": 199, "q": "При обстеженні жінки виявили перелом однієї з кісток черепа, ускладнений кровотечею з поперечної пазухи твердої оболонки мозку. Назвіть кістку, на якій розташовується борозна цієї пазухи:", "options": {"A": "Потилична", "B": "Тім’яна", "C": "Клиноподібна", "D": "Скронева", "E": "Лобова"}, "answer": "A", "score": 5.4, "prof": "med", "topic": "c1:m1:8"}, {"id": "fc399caa7d", "year": 2016, "years": [2016], "n": 199, "q": "У дитини рана позаду соскоподібного відростка черепа. З рани витікає яскраво-червона кров. Гілки якої артерії пошкоджені?", "options": {"A": "A. occipitalis", "B": "A. temporalis superior", "C": "A. maxillaris", "D": "A. carotis externa", "E": "A. carotis interna"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "a2713f0751", "year": 2015, "years": [2015], "n": 7, "q": "У хворого з аневризмою правої підключичної артерії спостерігається захриплість голосу. З подразненням якого нерву це може бути пов’язано?", "options": {"A": "N.laringeus reccurens dexter", "B": "N.laringeus superior dexter", "C": "N.laringeus reccurens sinister", "D": "N.laringeus superior sinister", "E": "N.laringeus inferior sinister"}, "answer": "A", "score": 9.8, "prof": "med", "tag": "angio"}, {"id": "4293dd56f8", "year": 2015, "years": [2014, 2015], "n": 53, "q": "У пацієнта внаслідок черепно-мозкової травми знижена шкірна чутливість. Яка ділянка кори великого мозку може бути ураженою?", "options": {"A": "Задня центральна звивина", "B": "Потилична ділянка", "C": "Поясна звивина", "D": "Лобна ділянка кори", "E": "Передня центральна звивина"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:8"}, {"id": "a340ac0fdc", "year": 2015, "years": [2013, 2015], "n": 58, "q": "При проведенні операції на тонкій кишці лікар виявив ділянку слизової оболонки, де на фоні колових складок була присутня поздовжня складка. Який відділ тонкої кишки має таку будову?", "options": {"A": "Pars descendens duodeni", "B": "Pars horizontalis duodeni", "C": "Pars ascendens duodeni", "D": "Початковий відділ jejunum", "E": "Дистальний відділ ileum"}, "answer": "A", "score": 7.9, "prof": "med", "topic": "c1:m1:29"}, {"id": "5bd5904e42", "year": 2015, "years": [2015], "n": 67, "q": "У хворого з довготривалим запаленням слизової оболонки носової порожнини з’явилися симптоми ураження слизової оболонки верхньощелепної пазухи (гайморит). Через яке утворення носової порожнини стало можливим розповсюдження інфекції?", "options": {"A": "Верхньощелепний отвір", "B": "Решітчаста лійка", "C": "Клино-піднебінний отвір", "D": "Клино-решітчаста заглибина", "E": "Решітчасті комірки"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:12"}, {"id": "62e9fbb096", "year": 2015, "years": [2015], "n": 80, "q": "В психіатричній клініці перебуває пацієнтка, яка не може згадати свого попереднього життя. Її випадково знайшли у місті, розташованому в протилежному кінці країни, де вона працювала офіціанткою в кафе. Перед зникненням жінка жила в рідному місті, де вже кілька років була монахинею в монастирі з власної волі i всупереч бажанню рідних. У пацієнтки:", "options": {"A": "Дисоціативна фуга", "B": "Соматизований розлад", "C": "Обсесивно-компульсивний розлад", "D": "Дисморфофобійний розлад", "E": "Посттравматичний стресовий розлад"}, "answer": "A", "score": 3.8, "prof": "stom", "topic": "c1:m2:8"}, {"id": "21989325ef", "year": 2015, "years": [2013, 2014, 2015], "n": 124, "q": "Внаслідок ДТП у потерпілої 37-ми років виникло неутримання сечі. Які сегменти спинного мозку пошкоджені?", "options": {"A": "S2 − S4", "B": "T h1 − T h5", "C": "L1 − L2", "D": "T h2 − T h5", "E": "T h1 − L1"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:1"}, {"id": "6acfc29d42", "year": 2015, "years": [2015], "n": 125, "q": "На молочній фермі були відібрані проби молока на вміст хлорорганічного пестициду ліндану. Розмір партії 1000 літрів. У токсикологічній лабораторії СЕС було виявлено, що вміст ліндану перевищує МДР у 4 рази. Дайте ріант, заключення про якість молока:", "options": {"A": "Недоброякісне", "B": "Доброякісне", "C": "Умовно придатне", "D": "Фальсифіковане", "E": "Біологічно цінний продукт"}, "answer": "A", "score": 3.8, "prof": "stom", "topic": "c1:m1:12"}, {"id": "87549904bb", "year": 2015, "years": [2015], "n": 129, "q": "Підчас апендектомії хворому перев’язали a. appendicularis. Гілкою якої артерії є означена судина?", "options": {"A": "A. ileocolica", "B": "A. colica dextra", "C": "A. colica media", "D": "A. sigmoidea", "E": "A. mesenterica inferior"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "33c544c3fe", "year": 2015, "years": [2015], "n": 137, "q": "У хворого 43-х років розвиток гострого панкреатиту супроводжується порушенням прохідності загальної жовчної протоки. До якого стану це може призвести?", "options": {"A": "Механічної жовтяниці", "B": "Гемолітичної жовтяниці", "C": "Паренхіматозної жовтяниці", "D": "Печінкової коми", "E": "Портальної гіпертензії"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:31"}, {"id": "1cfedec4df", "year": 2015, "years": [2015], "n": 145, "q": "У хворого виявлено ушкодження білої речовини спинного мозку в межах присередньої частини заднього канатику, порушення пропріоцептивної чутливості від суглобів та м’язів нижньої кінцівки. Які волокна уражені?", "options": {"A": "Fasciculus gracilis", "B": "Tr. spinothalamicus lateralis", "C": "Tr. spinocerebellaris anterior", "D": "Tr. spinocerebellaris posterior", "E": "Fasciculus cuneatus"}, "answer": "A", "score": 4.8, "prof": "med", "topic": "c1:m1:19"}, {"id": "c728ac27ff", "year": 2015, "years": [2015], "n": 146, "q": "У похилої людини зареєстрували зміну сили серцевих скорочень та фізичних властивостей судин, що чітко позначилося на графічному записі пульсових хвиль сонної артерії. Який метод було застосовано?", "options": {"A": "Сфігмографія", "B": "Плетизмографія", "C": "Реографія", "D": "Міографія", "E": "Флебографія"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "9b92e05341", "year": 2015, "years": [2015], "n": 147, "q": "У хворого на тлі інфаркту міокарда виникла пароксизмальна шлуночкова тахікардія. Який з перерахованих протиаритмічних засобів слід обрати, щоб не зменшити серцевий викид?", "options": {"A": "Лидокаїну гідрохлорид", "B": "Новокаїнамід", "C": "Верапаміл", "D": "Анаприлін", "E": "Калію хлорид"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "3db9d923a1", "year": 2015, "years": [2015], "n": 148, "q": "На північній околиці населеного пункт розташований хімічний комбінат. Протягом року спостерігається така повторюваність вітрів: північний - 10%, східний - 20%, південний - 50%, західний - 20%. Назвіть оптимальКрок 2 Медична психологія (україномовний ва не місце для розміщення земельної ділянки стаціонару медико-санітарної частини?", "options": {"A": "На південь від хімічного комбінату", "B": "На північ від хімічного комбінату", "C": "На схід від хімічного комбінату", "D": "На захід від хімічного комбінату", "E": "На території хімічного комбінату"}, "answer": "A", "score": 3.8, "prof": "stom"}, {"id": "1a4ac86634", "year": 2015, "years": [2015], "n": 163, "q": "Під час виконання оперативного втручання на гомілці хірург виділяє задню стінку canalis cruropopliteus. Яка анатомічна структура її утворює?", "options": {"A": "M.soleus", "B": "M.gastrocnemius", "C": "M.tibialis anterior", "D": "M.tibialis posterior", "E": "M.plantaris"}, "answer": "A", "score": 9.4, "prof": "med"}, {"id": "1ee8226ef2", "year": 2015, "years": [2015], "n": 174, "q": "У чоловіка 29-ти років з ножовим пораненням шиї спостерігається кровотеча. При первинній обробці рани встановлено, що пошкоджена судина, розташована вздовж латерального краю груднинноключично-соскоподібного м’яза. Визначте цю судину:", "options": {"A": "V. jugularis externa", "B": "V. jugularis anterior", "C": "A. carotis externa", "D": "A. carotis interna", "E": "V. jugularis interna"}, "answer": "A", "score": 5.4, "prof": "med", "tag": "angio"}, {"id": "333ef9c920", "year": 2015, "years": [2015], "n": 175, "q": "Жінка 35-ти років скаржиться на слабкість, часті випорожнення з домішками крові, зменшення ваги тіла на 8 кг за 6 місяців, періодично - підвищення температури до 37, 8o\u0002. Об’єктивно: to - 37, 5o C , Рs- 86/хв., АТ- 110/70 мм рт. ст. Шкіра бліда, пальпаторно живіт помірно болісний. У крові: Нв- 92 Крок 2 Медична психологія (україномовний ва г/л, ШЗЕ- 35 мм/год. Колоноскопія: слизова прямої та сигмоподібної кишки зерниста, гіперемована, набрякла, нерівномірно потовщена (псевдополіпи), кровить, на її поверхні - ерозії та виразки. Яка патологія найбільш імовірно викликала ураження кишки у хворої?", "options": {"A": "Виразковий коліт", "B": "Хвороба Крона", "C": "Синдром роздратованого кишечника", "D": "Рак прямої кишки", "E": "Поліпоз кишки"}, "answer": "A", "score": 4.2, "prof": "stom", "topic": "c1:m1:30"}, {"id": "0e3a9d20f1", "year": 2015, "years": [2015], "n": 188, "q": "Під час виконання операції на черевній порожнині хірург виділив зв’язку печінки, що проходить від передньої стінки черевної порожнини (пупка) до нижньої поверхні печінки. Яка це зв’язка?", "options": {"A": "Кругла зв’язка печінки", "B": "Серпоподібна зв’язка печінки", "C": "Вінцева зв’язка печінки", "D": "Венозна зв’язка печінки", "E": "Трикутна зв’язка"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:31"}, {"id": "83644298ca", "year": 2015, "years": [2015], "n": 192, "q": "До хірургічного відділення надійшов хворий з імовірним некрозом органів верхнього поверху черевної порожнини. З гострим порушенням кровообігу якої судини це пов’язано?", "options": {"A": "Truncus coeliacus", "B": "A. mesenterica inferior", "C": "A. mesenterica superior", "D": "A. iliaca communis", "E": "A. renalis"}, "answer": "A", "score": 5.3, "prof": "med", "tag": "angio"}, {"id": "ec0d9a2af0", "year": 2015, "years": [2015], "n": 194, "q": "Після травми на рентгенограмі тазу виявлена тріщина кістки, яка має затульну борозну. Яка це кістка?", "options": {"A": "Лобкова", "B": "Клубова", "C": "Крижова", "D": "Сіднична", "E": "Куприкова"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:6"}, {"id": "a6489654d2", "year": 2014, "years": [2014], "n": 10, "q": "В результаті травми пошкоджений спинний мозок (з повним розривом) на рівні першого шийного хребця. Що відбудеться з диханням?", "options": {"A": "Припиняється", "B": "Не змінюється", "C": "Зростає частота", "D": "Зростає глибина", "E": "Зменшується частота"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:2"}, {"id": "dfd26fa9e6", "year": 2014, "years": [2014], "n": 24, "q": "При операції правосторонньої лобектомії хірург підійшов до кореня правої легені з метою окремого виділення i обробки його складових. Вкажіть порядок розміщення елементів кореня правої легені з якими лікар зустрінеться при виділенні та обробці в напрямку зверху вниз?", "options": {"A": "Бронх, легенева артерія, легеневі вени", "B": "Легенева артерія, бронх, легеневі вени", "C": "Легенева вена, легеневі артерії, бронх", "D": "Бронх, легенева артерія, діафрагмальний нерв", "E": "Діафрагмальний нерв, бронх, бронхіальні артерія i вена"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "1a5c1b9a7e", "year": 2014, "years": [2014], "n": 27, "q": "У хворого під час трахеотомії виникла виражена кровотеча. Яка артерія була травмована під час операції?", "options": {"A": "A. thyroidea ima", "B": "A. thyroidea superior", "C": "A. thyroidea inferior", "D": "A. laryngea inferior", "E": "A. laryngea superior"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "4c94f83d1c", "year": 2014, "years": [2014], "n": 36, "q": "У пораненого перев’язали плечову артерію в нижній третині плеча. За рахунок яких артерій можливе відновлення кровопостачання передпліччя i кисті?", "options": {"A": "Глибока артерія плеча, ліктьові колатеральні артерії", "B": "М’язові гілки плечової артерії", "C": "Передні i задні огинаючі артерії плеча", "D": "Підлопаткова, передня міжкісткова артерія", "E": "Грудонадплечова, задня огинаюча артерія плеча"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "66c88cdd44", "year": 2014, "years": [2014], "n": 41, "q": "У хворої 28-ми років виявлена пухлина яєчника i показана операція по його видаленню. При здійсненні її необхідно розтинати зв’язку, що з’єднує яєчник з маткою. Яку зв’язку повинен перерізати хірург?", "options": {"A": "Lig. Ovarii proprium", "B": "Lig. Latum uteri", "C": "Lig. Cardinali", "D": "Lig.umbilicale laterale", "E": "Lig. Suspensorium ovarii"}, "answer": "A", "score": 5.7, "prof": "med", "topic": "c1:m1:38"}, {"id": "305e1a6090", "year": 2014, "years": [2014], "n": 91, "q": "У чоловіка при обстеженні виявлено порушення кровообігу міокарда лівого передсердя. У басейні якої артерії відбулись порушення кровообіовний гу?", "options": {"A": "Ліва вінцева", "B": "Права вінцева", "C": "Права та ліва вінцеві", "D": "Передня міжшлуночкова гілка лівої вінцевої артерії", "E": ""}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "afdbb91159", "year": 2014, "years": [2014], "n": 94, "q": "Швидкість проведення збудження нервовими волокнами становить 120 м/сек. Який з наведених чинників, перш за все, забезпечує таку швидкість?", "options": {"A": "Наявність мієлінової оболонки", "B": "Великий потенціал спокою", "C": "Велика амплітуда потенціалу дії", "D": "Малий поріг деполяризації", "E": "Великий фактор надійності"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:11"}, {"id": "62cf089074", "year": 2014, "years": [2014], "n": 127, "q": "В результаті травми порушено цілісність переднього корінця спинного мозку. Які відростки яких нейронів при цьому пошкоджені?", "options": {"A": "Аксони рухових нейронів", "B": "Дендрити рухових нейронів", "C": "Аксони чутливих нейронів", "D": "Дендрити чутливих нейронів", "E": "Дендрити вставних нейронів"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:1"}, {"id": "0ccd0de0d9", "year": 2013, "years": [2013, 2014], "n": 193, "q": "У чоловіка 29-ти років з ножовим пораненням шиї визначається кровотеча. При первинній обробці рани встановлено, що пошкоджена судина, розташована вздовж латерального краю груднинно-ключично-соскоподібного м’яза. Визначте цю судину:", "options": {"A": "V. jugularis externa", "B": "V. jugularis anterior", "C": "A. carotis externa", "D": "A. carotis interna", "E": "V. jugularis interna"}, "answer": "A", "score": 5.4, "prof": "med", "tag": "angio"}, {"id": "8d0d63598c", "year": 2013, "years": [2013], "n": 18, "q": "Хворий 61-го року страждає на цироз печінки. Варикозні розширення яких вен з системи порто-кавальних анастомозів можуть мати місце у хворого?", "options": {"A": "V. epigastrica superficialis", "B": "V. femoralis", "C": "V. subcostalis", "D": "V. circumflexa ilium profunda", "E": "Vv. intercostales posteriores"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "39e52fcfe2", "year": 2013, "years": [2013], "n": 20, "q": "Хворий 34-х років страждає на туберкульоз легень з дитинства. Йому призначена операція. Під час операції у хворого була видалена середня доля правої легені. Які сегменти були видалені?", "options": {"A": "Латеральний i медіальний", "B": "Верхній i передній", "C": "Медіальний базальний i латеральний базальний", "D": "Верхній язичковий i нижній язичковий", "E": "Задній i передній"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:35"}, {"id": "8a82040d6a", "year": 2013, "years": [2013], "n": 27, "q": "У різнороба 55-ти років, який 28 років пропрацював на хімічному заводі в цеху зі шкідливими умовами виробництва, спостерігаються часті кровотечі із слизової оболонки носової порожнини. За рахунок яких артерій це відбувається?", "options": {"A": "Передня i задня решітчасті артерії", "B": "Надочноямкова артерія", "C": "Війчасті артерії", "D": "Передня мозкова артерія", "E": "Очна артерія"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "f45cc785fb", "year": 2013, "years": [2013], "n": 55, "q": "Перебуваючи у робочому відрядженні в одній із країн тропічної Африки, лікар зіткнувся зі скаргами місцевого населення з приводу хвороби дітей 10-14 років, що супроводжується стійкими лихоманками, які не мають правильного чергування, виснаженням, анемією, збільшенням печінки i селезінки. Враховуючи місцеві умови, що пов’язані з великою кількістю москітів, можна передбачити що це:", "options": {"A": "Вісцеральний лейшманіоз", "B": "Балантидіаз", "C": "Токсоплазмоз", "D": "Сонна хвороба", "E": "Хвороба Чагаса"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:31"}, {"id": "ce7df9ce14", "year": 2013, "years": [2013], "n": 65, "q": "Чоловіку 44-х років за вимогою діагностичних тестів зробили лімфографію органів грудної порожнини. Хірург встановив, що пухлина вразила орган, з лімфатичних судин якого лімфа безпосередньо переходить у грудну протоку. Який це орган?", "options": {"A": "Стравохід", "B": "Трахея", "C": "Лівий головний бронх", "D": "Серце", "E": "Осердя"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "b5389a9710", "year": 2013, "years": [2013], "n": 118, "q": "У ході хірургічної операції на нирці із заднього доступу (з боку спини) виникла необхідність перетиснути ниркову артерію. У якій послідовності розташовані елементи ниркової ніжки у її воротах ззаду наперед?", "options": {"A": "Сечовід, артерія, вена", "B": "Артерія, сечовід, вена", "C": "Артерія, вена, сечовід", "D": "Вена, сечовід, артерія", "E": "Вена, артерія, сечовід"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "d6f1ab2b70", "year": 2013, "years": [2013], "n": 134, "q": "Для постійного внутрішньовенного ведення ліків хворому краще встановити підключичний катетер. В якому анатомічному утворенні на шиї потрібно шукати підключичну вену?", "options": {"A": "Spatium antesсalenum", "B": "Spatium interscalenum", "C": "Fossa retromandibularis", "D": "Spatium interaрoneuroticum suprasternale", "E": ""}, "answer": "A", "score": 4.5, "prof": "med", "tag": "angio"}, {"id": "10dd984f30", "year": 2013, "years": [2013], "n": 137, "q": "У потерпілого 35-ти років з травмою голови у скроневій ділянці діагностовано епідуральну гематому. Яка з артерій найімовірніше пошкоджена?", "options": {"A": "Середня оболонкова", "B": "Середня мозкова", "C": "Поверхнева скронева", "D": "Передня оболонкова", "E": "Задня вушна"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "c27b44be46", "year": 2013, "years": [2013], "n": 138, "q": "В результаті травми порушено цілісність переднього корінця спинного мозку. Які відростки яких нейронів при цьому пошкоджені? ний", "options": {"A": "Аксони рухових нейронів", "B": "Дендрити рухових нейронів", "C": "Аксони чутливих нейронів", "D": "Дендрити чутливих нейронів", "E": "Дендрити вставних нейронів"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:1"}, {"id": "1820c53d62", "year": 2013, "years": [2013], "n": 174, "q": "У студента 19-ти років запальний процес у крилопіднебінній ямці. Інфекція поширилась в середню черепну ямку. Через яке анатомічне утворення розповсюдилась інфекція?", "options": {"A": "Foramen rotundum", "B": "Foramen sphenopalatinum", "C": "Canalis palatinus major", "D": "Canalis palatinus minor", "E": "Canalis ptherygoideus"}, "answer": "A", "score": 8.2, "prof": "med", "topic": "c1:m1:12"}, {"id": "cba2f15809", "year": 2012, "years": [2012], "n": 33, "q": "У хворого запалення легень ускладнилось ексудативним плевритом. В якому з перелічених анатомічних утворень переважно може накопичуватися рідина? ний", "options": {"A": "Sinus costodiaphragmaticus pleurae", "B": "Sinus costomediastinalis pleurae", "C": "Sinus phrenicomediastinalis pleurae", "D": "Sinus transversus pericardii", "E": "Sinus obliquus pericardii"}, "answer": "A", "score": 4.8, "prof": "med", "topic": "c1:m1:35"}, {"id": "6fa9918fc0", "year": 2012, "years": [2012], "n": 40, "q": "До реанімаційного відділення надійшов хворий з ознаками гострого отруєння морфіном. Який засіб необхідно використати у даному випадку для промивання шлунку?", "options": {"A": "Калію перманганат", "B": "Натрію гідрокарбонат", "C": "Фурацилін", "D": "Розчин натрію хлориду", "E": "Борна кислота"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:29"}, {"id": "0f2154131f", "year": 2012, "years": [2012], "n": 44, "q": "Жінка 45-ти років, перукар, скаржиться на болі у ногах, що з’являються після роботи, ввечері та вночі. При огляді хворої виявлено варикозне розширені вени на присередній поверхні гомілки та стегна. Яка вена та її безпосередні протоки розширені?", "options": {"A": "Велика підшкірна", "B": "Стегнова", "C": "Мала підшкірна", "D": "Глибока вена стегна", "E": "Передня великогомілкова вена"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "a99c59cfee", "year": 2011, "years": [2011, 2012], "n": 74, "q": "Хворому встановлений діагноз ураження голівки стегна ішемічного походження. Яка артерія ушкоджена?", "options": {"A": "Ramus acetabularum A.obturatoriae", "B": "Arteria femoralis", "C": "Arteria illiaca externa", "D": "Arteria profunda femoris", "E": "Arteria umbilicalis"}, "answer": "A", "score": 7.8, "prof": "med", "tag": "angio"}, {"id": "48dc1be48f", "year": 2012, "years": [2012], "n": 79, "q": "Під час операції видалення матки з яєчниками i матковими трубами лікар перев’язує зв’язку, що підвішує яєчник. Які судини перев’язав лікар в цій зв’язці?", "options": {"A": "Яєчникові артерія i вена", "B": "Маткові артерія i вена", "C": "Трубні артерія i вена", "D": "Внутрішня клубова артерія", "E": "Внутрішня клубова вена"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "bb38e817c1", "year": 2012, "years": [2012], "n": 80, "q": "При проведенні операцїї на тонкій кишці лікар виявив ділянку слизової оболонки, де на фоні колових складок була присутня поздовжня складка. Який відділ тонкої кишки має таку будову?", "options": {"A": "Pars descendens duodeni", "B": "Pars horizontalis duodeni", "C": "Pars ascendens duodeni", "D": "Початковий відділ jejunum", "E": "Дистальний відділ ileum"}, "answer": "A", "score": 7.9, "prof": "med", "topic": "c1:m1:29"}, {"id": "2d6a51db0b", "year": 2012, "years": [2012], "n": 88, "q": "Під час обстеження хворої виникла підозра на наявність гнійного випоту в прямокишково-матковому заглибленні. Через яке анатомічне утворення найкраще пропунктувати дане заглиблення?", "options": {"A": "Заднє склепіння піхви", "B": "Переднє склепіння піхви", "C": "Ампула прямої кишки", "D": "Діафрагма тазу", "E": "Передня стінка піхви"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:18"}, {"id": "ee8ed196c0", "year": 2012, "years": [2012], "n": 89, "q": "Хворий 35-ти років звернувся зі скаргами на біль та набряк в ділянці дна ротової порожнини. Діагностовано запальний процес у ділянці вивідної протоки піднижньощелепної слинної залози. Куди відкривається ця протока?", "options": {"A": "Caruncula sublingualis", "B": "Vestibulum oris", "C": "Foramen caecum linguae", "D": "Plica fimbriata", "E": "Recesus gingivalis"}, "answer": "A", "score": 3.7, "prof": "med", "topic": "c1:m1:11"}, {"id": "23a12f1789", "year": 2011, "years": [2011], "n": 2, "q": "Внаслідок інсульту (крововилив в головний мозок) у хворого відсутні вольові рухи м’язів голови i шиї. Обстеження головного мозку за допомогою ЯМР показало, що гематома знаходиться в коліні внутрішньої капсули. Який провідний шлях пошкоджено у хворого?", "options": {"A": "Tr.cortico-nuclearis", "B": "Tr.cortico-spinalis", "C": "Тr.cortico-thalamicus", "D": "Tr.cortico-fronto-pontinus", "E": "Tr.thalamo-corticalis"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:17"}, {"id": "ffeb3bc94a", "year": 2009, "years": [2009, 2011], "n": 16, "q": "У хворого 70-ти років атеросклероз ускладнився тромбозом судин нижніх кінцівок, виникла гангрена пальців лівої стопи. Початок тромбоутворення, найбільш вірогідно, пов’язаний з:", "options": {"A": "Адгезією тромбоцитів", "B": "Активацією протромбінази", "C": "Перетворенням протромбіну в тромбін", "D": "Перетворенням фібриногену в фібрин", "E": "Зниженням синтезу гепарину"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "314de5ce01", "year": 2011, "years": [2011], "n": 35, "q": "Під час ревізії порожнини очеревини з приводу перитоніту виявлений обмежений гнійник у кореня брижі сигмоподібної кишки. У якому утворенні очеревини знаходиться гнійник?", "options": {"A": "Міжсигмоподібна ямка", "B": "Правий брижовий синус", "C": "Правий бічний канал", "D": "Лівий бічний канал", "E": "Лівий брижовий синус"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:30"}, {"id": "c99de1f64c", "year": 2011, "years": [2011], "n": 41, "q": "На ізольованому серці вивчалась швидкість проведення збудження у різних його ділянках. Де була виявлена найменша швидкість?", "options": {"A": "Атріовентрикулярний вузол", "B": "Пучок Гіса", "C": "Волокна Пуркін’є", "D": "Міокард передсердь", "E": "Міокард шлуночків"}, "answer": "A", "score": 3.8, "prof": "med", "tag": "angio"}, {"id": "d4e0e322f0", "year": 2010, "years": [2010, 2011], "n": 46, "q": "У хворого гнійне запалення клиноподібної пазухи. В яку частину носової порожнини витікає гній?", "options": {"A": "Meatus nasi superior", "B": "Meatus nasi communis", "C": "Meatus nasi medius", "D": "Meatus nasi inferior", "E": ""}, "answer": "A", "score": 8.2, "prof": "med", "topic": "c1:m1:12"}, {"id": "dfb5e1bbec", "year": 2011, "years": [2011], "n": 48, "q": "Внаслідок травми у чоловіка 40-ка років зруйновані задні корінці спинного мозку. Які розлади будуть спостерігатися в зоні іннервації цих корінців?", "options": {"A": "Втрата всіх видів чутливості", "B": "Порушення функції посмугованих скелетних м’язів", "C": "Порушення функції гладеньких м’язів", "D": "Втрата температурної та вібраційної чутливості", "E": "Втрата больової чутливості"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:1"}, {"id": "46f875d602", "year": 2011, "years": [2011], "n": 49, "q": "До клініки госпіталізована пацієнтка із скаргами на кровохаркання, піний тливість. Рентгенологічно виявлено вогнище туберкульозу у верхній частці правої легені. Показана операція. Яку кількість сегментів можна видалити в складі верхньої частки правої легені?", "options": {"A": "3", "B": "5", "C": "4", "D": "2", "E": "1"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:35"}, {"id": "52f2dfae47", "year": 2011, "years": [2011], "n": 73, "q": "Хвора скаржиться на набряк ніг, посиніння шкіри, невеличкі виразки збоку латерального виростку. При обстеженні відмічено: припухлість, збільшення розмірів вен, утворення вузлів. З боку якої вени відмічається патологія?", "options": {"A": "V. saphena parva", "B": "V. saphena magna", "C": "V. femoralis", "D": "V. profunda femoris", "E": "V. iliaca externa"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:16"}, {"id": "2f3b09c3a0", "year": 2011, "years": [2011], "n": 87, "q": "При медичному обстеженні у військкоматі у юнака 18-ти років виявлено опускання головки надп’ясткової кістки, що призвело до плоскостопості. Зі слабкістю якої зв’язки стопи це пов’язано?", "options": {"A": "Підошвова п’ятково-човноподібна", "B": "Надп’ятково-човноподібна", "C": "Підошвова клино-кубоподібна", "D": "Міжкісткова клино-кубоподібна", "E": "Роздвоєна"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:5"}, {"id": "c76b213c4d", "year": 2010, "years": [2010, 2011], "n": 139, "q": "У пацієнта діагностовано компресійний перелом поперекового хребця. При цьому різко збільшилась кривизна лордозу поперекового відділу хребта. Ушкодженням якої зв’язки може супроводжуватись така зміна кривизни хребта?", "options": {"A": "Передня поздовжня", "B": "Задня поздовжня", "C": "Жовта", "D": "Клубово-поперекова", "E": "Міжостиста"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:2"}, {"id": "1e9571c4cb", "year": 2011, "years": [2011], "n": 194, "q": "У хворого при томографічному обстеженні було виявлено пухлину відділу мозку з ушкодженням ядер XI та XII пар черепних нервів. Який це відділ мозку?", "options": {"A": "Myelencephalon", "B": "Telencephalon", "C": "Mesencephalon", "D": "Metencephalon", "E": "Diencephalon"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:8"}, {"id": "4d3392ce93", "year": 2010, "years": [2010], "n": 23, "q": "До клініки надійшов хворий зі скаргами на біль у правій підреберній ділянці, блювання з кров’ю. При дослідженні було встановлено збільшення печінки, розширення підшкірних вен передньої стінки живота. В якій судині утруднений ний кровотік?", "options": {"A": "Ворітна вена", "B": "Черевна аорта", "C": "Печінкові вени", "D": "Нижня порожниста вена", "E": "Верхня порожниста вена"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "8635e1e6e8", "year": 2010, "years": [2010], "n": 51, "q": "У потерпілого в аварії спостерігається кровотеча з м’яких тканин попереду від кута нижньої щелепи. Яку судину необхідно перев’язати для зупинки кровотечі?", "options": {"A": "A.facialis", "B": "A.carotis interna", "C": "A.temporalis superficialis", "D": "A.alveolaris inferior", "E": "A.lingvalis"}, "answer": "A", "score": 8.2, "prof": "med", "tag": "angio"}, {"id": "7db9fe9198", "year": 2010, "years": [2010], "n": 87, "q": "При оперативному втручанні з приводу каменів жовчних ходів хірург повинен знайти загальну печінкову протоку. Між листками якої зв’язки вона знаходиться?", "options": {"A": "Печінково-дванадцятипала", "B": "Печінково-шлункова", "C": "Печінково-ниркова", "D": "Кругла зв’язка печінки", "E": "Венозна зв’язка"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:29"}, {"id": "ca4262c0c2", "year": 2010, "years": [2010], "n": 110, "q": "У важкоатлета при підйомі штанги відбувся розрив грудної лімфатичної протоки. Вкажіть найбільш вірогідне місце пошкодження:", "options": {"A": "У ділянці аортального отвору діафрагми", "B": "У ділянці попереково-крижового зчленування", "C": "У задньому середостінні", "D": "У місці впадіння у венозний кут", "E": "У ділянці шиї"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "a76ef28cae", "year": 2010, "years": [2010], "n": 176, "q": "У потерпілого з травмою голови у скроневій ділянці діагностовано епідуральну гематому. Яка з артерій найвірогідніше пошкоджена?", "options": {"A": "Середня оболонкова", "B": "Середня мозкова", "C": "Поверхнева скронева", "D": "Передня оболонкова", "E": "Задня вушна"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "142ab8253b", "year": 2010, "years": [2010], "n": 186, "q": "Жінка похилого віку госпіталізована зі скаргами на різкий біль, набряк в ділянці правого кульшового суглоба, що з’явилися після падіння. Об’єктивно: стегно приведене досередини, рухи в кульшовому суглобі порушені. Перелом якої кістки або її частини визначив лікар?", "options": {"A": "Шийка стегнової кістки", "B": "Тіло стегнової кістки", "C": "Виростки стегнової кістки", "D": "Лобкова кістка", "E": "Сіднична кістка"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:6"}, {"id": "27f3f67194", "year": 2009, "years": [2009], "n": 56, "q": "Хвора скаржиться на набряк ніг, (україномовний варіант) посиніння шкіри, невеличкі виразки збоку латерального виростку. При обстеженні відмічено: припухлість, збільшення розмірів вен, утворення вузлів. З боку якої вени відмічається патологія?", "options": {"A": "V. saphena parva", "B": "V. saphena magna", "C": "V. femoralis", "D": "V. profunda femoris", "E": "V. iliaca externa"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m2:16"}, {"id": "58e121c5bc", "year": 2007, "years": [2007, 2009], "n": 59, "q": "Хвора 48-ми років надійшла до клініки із скаргами на слабкість, дратівливість, порушення сну. Об’єктивно: шкіра та склери жовтого кольору. У крові: підвищення рівня загального білірубіну з переважанням прямого. Кал - ахолічний. Сеча - темного кольору (жовчні пігменти). Яка жовтяниця має місце в хворої?", "options": {"A": "Механічна", "B": "Гемолітична", "C": "Паренхіматозна", "D": "Синдром Жільбера", "E": "Синдром Кріглера-Найяра (україномовний варіант)"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:31"}, {"id": "bfc99c61f4", "year": 2009, "years": [2009], "n": 90, "q": "У хворого на рак спинки язика виникла сильна кровотеча внаслідок ураження пухлиною дорзальної артерії язика. Яку судину повинен перев’язаукраїномовний варіант) ти лікар для зупинки кровотечі?", "options": {"A": "Язикова артерія", "B": "Дорзальна артерія язика", "C": "Глибока артерія язика", "D": "Лицева артерія", "E": "Висхідна артерія глотки"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "c0dd3d6b14", "year": 2009, "years": [2009], "n": 159, "q": "Після черепно-мозкової травми у хворого спостерігається втрата можливості виконувати знайомі до травми складно-координовані рухи (апраксія). В якій ділянці кори великих півкуль найімовірніше локалізується ушкодження?", "options": {"A": "Gyrus supramarginalis", "B": "Gyrus angularis", "C": "Gyrus paracentralis", "D": "Gyrus lingualis", "E": "Gyrus parahippocampalis"}, "answer": "A", "score": 9.8, "prof": "med", "topic": "c1:m1:8"}, {"id": "1dce159842", "year": 2009, "years": [2009], "n": 198, "q": "Постраждалого в аварії водія госпіталізовано до стаціонару з ушкодженням медіального надвиростка плечової кістки. Який нерв при цьому може бути ушкоджений?", "options": {"A": "n. ulnaris", "B": "n. radialis", "C": "n. axillaris", "D": "n. muscolocutaneus", "E": "n. medianus"}, "answer": "A", "score": 4.6, "prof": "med", "topic": "c1:m1:1"}, {"id": "20feef62ba", "year": 2008, "years": [2008, 2009], "n": 199, "q": "Чоловік з колотою раною в ділянці чотирьохстороннього отвору звернувся до лікаря. При обстеженні виявлено, що потерпілий не може відвести руку україномовний варіант) від тулуба. Який нерв вірогідно ушкоджений?", "options": {"A": "N.axillaris", "B": "N.medianus", "C": "N.radialis", "D": "N.ulnaris", "E": "N.subclavius"}, "answer": "A", "score": 9.8, "prof": "med"}, {"id": "8c984f3e8e", "year": 2008, "years": [2008], "n": 5, "q": "Під час лапаротомії хірург виявив гангренозне ураження низхідної ободової кишки. Тромбоз якої артерії зумовив цей стан?", "options": {"A": "Ліва ободова", "B": "Серединна ободова", "C": "Права ободова", "D": "Клубово-ободова", "E": "Верхня брижова (україномовний варіант)"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "3bcf490143", "year": 2008, "years": [2008], "n": 33, "q": "Жінці виконана операція з приводу позаматкової (трубної) вагітності. Гілки яких артерій має перев’язати хірург під час операції?", "options": {"A": "Маткова та яєчникова", "B": "Верхня міхурна та яєчникова", "C": "Нижня міхурна та яєчникова", "D": "Маткова та верхня міхурна", "E": "Маткова та нижня міхурна"}, "answer": "A", "score": 4.2, "prof": "med", "tag": "angio"}, {"id": "219b3a717a", "year": 2008, "years": [2008], "n": 91, "q": "У хворого на жовчнокам’яну хворобу розвинулася механічна жовтяниця. Під час обстеження встановлено, що камінь знаходиться у загальній жовчній протоці. Які жовчовивідні протоки утворюють обтуровану протоку?", "options": {"A": "Ductus hepaticus communis et ductus cysticus", "B": "Ductus hepaticus dexter et sinister", "C": "Ductus hepaticus dexter et ductus cysticus", "D": "Ductus hepaticus sinister et ductus cysticus", "E": "Ductus hepaticus communis et ductus choledochus"}, "answer": "A", "score": 7.8, "prof": "med", "topic": "c1:m1:31"}, {"id": "5c5a6f3420", "year": 2008, "years": [2008], "n": 131, "q": "При виконанні оперативного втручання в ділянці пахвової порожнини, хірургу необхідно виділити артеріальну судину, що оточена пучками плечового сплетіння. Яка це артерія?", "options": {"A": "A.axillaris", "B": "A.vertebralis", "C": "A.transversa colli", "D": "A.profunda brachii", "E": "A.subscapularis"}, "answer": "A", "score": 9.8, "prof": "med", "tag": "angio"}, {"id": "1fd3a0433c", "year": 2008, "years": [2008], "n": 145, "q": "До реанімаційного відділення надійшов чоловік з пораненням задньої ділянки шиї (regio nuchae). Який з м’язів тіла займає цю ділянку?", "options": {"A": "M.trapezius", "B": "M.sternocleidomastoideus", "C": "M.latissimus dorsi", "D": "M.rhomboideus minor", "E": "M.scalenus anterior"}, "answer": "A", "score": 9.4, "prof": "med", "topic": "c1:m1:22"}, {"id": "25b63ddf6d", "year": 2008, "years": [2008], "n": 198, "q": "До клініки швидкої допомоги надійшов хворий з ножовим пораненням лівої поперекової ділянки. У ході операції хірург встановив, що внутрішні органи не пошкоджені, але лезо ножа пошкодило один із м’язів ниркового ложа. Назвіть цей м’яз:", "options": {"A": "Великий поперековий м’яз", "B": "Клубовий м’яз", "C": "Випрямляч хребта", "D": "Внутрішній косий м’яз живота", "E": "Зовнішній косий м’яз живота"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:19"}, {"id": "a6ecb4cecd", "year": 2007, "years": [2007], "n": 5, "q": "Постраждалому з колотою раною передньої стінки шлунка наддається хірургічна допомога. До якого утворення порожнини очеревини потрапив вміст шлунка? (україномовний варіант)", "options": {"A": "Передшлункова сумка", "B": "Сальникова сумка", "C": "Печінкова сумка", "D": "Лівий мезентеріальний синус", "E": "Правий мезентеріальний синус"}, "answer": "A", "score": 4.2, "prof": "med", "topic": "c1:m1:29"}, {"id": "700dd792b6", "year": 2007, "years": [2007], "n": 68, "q": "До приймального відділення доставлено чоловіка з різаною раною підошви правої стопи. У постраждалого обмежене підняття латерального краю стопи. Під час обробки виявлено пошкодження сухожилка м’яза. Який м’яз ушкоджений? (україномовний варіант)", "options": {"A": "Довгий малогомілковий", "B": "Передній великогомілковий", "C": "Довгий розгинач пальців", "D": "Триголовий м’яз гомілки", "E": "Короткий малогомілковий"}, "answer": "A", "score": 3.8, "prof": "med", "topic": "c1:m1:7"}, {"id": "31ac73e188", "year": 2007, "years": [2007], "n": 87, "q": "Внаслідок аварії у постраждалого виникли сильний біль та набряк передньої поверхні гомілки; тильне згинання ступні утруднене. Функція якого з названих м’язів гомілки постраждала?", "options": {"A": "M.tibialis anterior", "B": "M.f lexor digitorum longus", "C": "M.f lexor hallucis longus", "D": "M.peroneus longus", "E": "M.peroneus brevis"}, "answer": "A", "score": 7.0, "prof": "med", "topic": "c1:m1:7"}, {"id": "6a7b78f250", "year": 2007, "years": [2007], "n": 97, "q": "У хворого на рак спинки язика виникла сильна кровотеча внаслідок ураження пухлиною дорзальної артерії язика. Яку судину повинен перев’язати лікар для зупинки кровотечі?", "options": {"A": "Язикова артерія", "B": "Дорзальна артерія язика", "C": "Глибока артерія язика", "D": "Лицева артерія", "E": "Висхідна артерія глотки"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "ba08133ba3", "year": 2007, "years": [2007], "n": 105, "q": "У дитини 2-х років після грипу з’явилися скарги на біль у вусі. Лікар виявив зниження слуху та запалення середнього вуха. Яким шляхом інфекція потрапила до середнього вуха?", "options": {"A": "Через слухову трубу", "B": "Через f oramen jugularis", "C": "Через canalis caroticus", "D": "Через atrium mastoideum", "E": "Через canalis nasolacrimalis"}, "answer": "A", "score": 4.0, "prof": "med"}, {"id": "3cc9eb16f7", "year": 2007, "years": [2007], "n": 149, "q": "Під час операції у пацієнта було видалено частину легені, яка вентилюється бронхом третього порядку, що супроводжується гілками легеневої артерії та інших судин. Яка частина легені була видалена?", "options": {"A": "Сегмент легені", "B": "Середня частка", "C": "Нижня частка", "D": "Верхня частка", "E": "Легенева часточка"}, "answer": "A", "score": 5.0, "prof": "med", "tag": "angio"}, {"id": "68847b6efd", "year": 2007, "years": [2007], "n": 171, "q": "У хворого 65-ти років під час неврологічного обстеження виявлено крововилив у межах верхньої скроневої звивини. У зоні кровопостачання якої артерії воно знаходиться?", "options": {"A": "Середня мозкова артерія", "B": "Передня мозкова артерія", "C": "Задня мозкова артерія", "D": "Передня сполучна артерія", "E": "Основна артерія"}, "answer": "A", "score": 4.6, "prof": "med", "tag": "angio"}, {"id": "088052ae4c", "year": 2007, "years": [2007], "n": 172, "q": "Чоловік 70-ти років під час гоління зрізав гнійник в ділянці соскоподібного", "options": {"A": "V.emissariae mastoideae", "B": "V.v.labyrinthi", "C": "V.v.tympanicae", "D": "V.f acialis", "E": "V.v.auriculares"}, "answer": "A", "score": 6.0, "prof": "med", "topic": "c1:m2:14"}, {"id": "6525e471ce", "year": 2007, "years": [2007], "n": 189, "q": "У чоловіка після черепно-мозкової травми виникла правобічна косоокість, що сходиться. Пошкодження якого черепно-мозкового нерва призвело до таких наслідків?", "options": {"A": "n.abducens", "B": "n.f acialis", "C": "n.trigeminus", "D": "n.trochlearis", "E": "n.oculomotorius"}, "answer": "A", "score": 8.6, "prof": "med", "topic": "c1:m1:8"}, {"id": "3298613f2b", "year": 2007, "years": [2007], "n": 190, "q": "При проникаючому пораненні передньої черевної стінки раневий канал пройшов над малою кривиною шлунка. Яке утворення очеревини найвірогідніше пошкоджене?", "options": {"A": "Ligamentum hepatogastricum", "B": "Ligamentum gastrocolicum", "C": "Ligamentum hepatoduoduodenale", "D": "Ligamentum hepatorenale", "E": "Ligamentum triangulare sinistrum"}, "answer": "A", "score": 11.4, "prof": "med", "topic": "c1:m1:29"}]};
